-- 013: the `analytics` schema (read-only, friendly-named VIEWS over the marketing data) and COMMENT ON for every documented marketing table, view and column.
--
-- Everything above the "comments" marker is hand-written DDL; everything below it is GENERATED by `python scripts/gen_schema_doc.py --emit-migration 013`
-- from docs/schema/descriptions.py (so psql \d+, DBeaver and agents that introspect see the same text as docs/DATA_SCHEMA.md).
-- Additive and idempotent (CREATE OR REPLACE VIEW, COMMENT ON). Once applied this file is immutable: a later view change goes in a NEW migration,
-- a later description change in a NEW migration written with `gen_schema_doc.py --comments all`.
--
-- analytics = views over public tables, owned by the migration role, so a role that has SELECT on a view can read it without any privilege on the public
-- tables behind it (views run with their owner's rights). etl.reader_role grants exactly that and nothing else.
-- NOT in here on purpose: feed_oauth (a credential), schema_migrations, every proj_* projection table that holds finance (P&L, financing, scenarios,
-- LOI / seller note, QuickBooks actuals, purchase orders, vendor costs) and anything that serves login or sessions (the app has no such tables).

CREATE SCHEMA IF NOT EXISTS analytics;

-- ---------------------------------------------------------------------------------------------------------------- dimensions
-- One row per Meta ad. product_slug follows the Products table's rule: a Meta family that maps to a tracker family counts under the product of that
-- family's FIRST tracker row; a family off the tracker keeps the product guessed from its name / campaign / ad set (unmatched_meta); no active product -> NULL.
CREATE OR REPLACE VIEW analytics.meta_ads AS
SELECT a.ad_id,
       a.account,
       a.ad_name,
       a.family_name,
       a.meta_family_key AS family_key,
       fm.tracker_family_key,
       p.slug AS product_slug,
       p.name AS product_name,
       a.campaign_id,
       c.name AS campaign_name,
       c.stage,
       a.adset_id,
       a.adset_name,
       a.status,
       (a.status = 'ACTIVE') AS is_active,
       a.created_date,
       a.first_day,
       a.last_day,
       l.spend       AS lifetime_spend,
       l.impressions AS lifetime_impressions,
       l.link_clicks AS lifetime_link_clicks,
       l.purchases   AS lifetime_purchases,
       l.conv_value  AS lifetime_revenue
FROM public.meta_ads a
LEFT JOIN public.meta_campaigns c ON c.campaign_id = a.campaign_id
LEFT JOIN public.meta_family_map fm ON fm.meta_family_key = a.meta_family_key
LEFT JOIN (
    SELECT DISTINCT ON (x.meta_family_key) x.meta_family_key, x.product_id
    FROM (
        SELECT m.meta_family_key, am.product_id, 1 AS pri
        FROM public.meta_family_map m
        JOIN public.ad_metrics am ON am.family_key = m.tracker_family_key AND am.is_first_row AND NOT starts_with(am.family_key, 'id:')
        JOIN public.tracker_rows tr ON tr.id = am.tracker_row_id AND tr.deleted_at IS NULL
        JOIN public.products pr ON pr.id = am.product_id AND pr.active
        UNION ALL
        SELECT u.meta_family_key, CASE WHEN pr.active THEN u.product_id END, 2 AS pri
        FROM public.unmatched_meta u LEFT JOIN public.products pr ON pr.id = u.product_id
    ) x
    ORDER BY x.meta_family_key, x.pri
) pa ON pa.meta_family_key = a.meta_family_key
LEFT JOIN public.products p ON p.id = pa.product_id
LEFT JOIN public.meta_ad_lifetime l ON l.ad_id = a.ad_id;

-- ---------------------------------------------------------------------------------------------------------------- Meta
-- Ad x day. The Meta columns come from ad_daily (Graph API, Meta-reported), the upstack_* columns from ad_daily_upstack (Upstack any-click 30-day
-- attribution mapped to ads). Any-click credits an ad on days it had no spend (an order credits every ad clicked in the 30 days before it), so
-- Upstack-only ad-days exist: their Meta columns are 0. upstack_* is NULL on days Upstack was not pulled, never 0.
CREATE OR REPLACE VIEW analytics.meta_ad_daily AS
SELECT k.day,
       k.ad_id,
       a.ad_name,
       a.product_slug,
       a.campaign_id,
       a.campaign_name,
       a.stage,
       a.adset_id,
       a.adset_name,
       a.account,
       k.source,
       k.spend,
       k.impressions,
       k.link_clicks,
       k.meta_purchases,
       k.meta_revenue,
       k.upstack_new_customers,
       k.upstack_new_customer_revenue,
       k.upstack_orders,
       k.upstack_order_revenue
FROM (
    SELECT u.day, u.ad_id,
           max(u.source) FILTER (WHERE NOT u.is_up) AS source,
           sum(u.spend) AS spend,
           CASE WHEN bool_or(NOT u.is_up) THEN sum(u.impressions) FILTER (WHERE NOT u.is_up) ELSE 0 END AS impressions,
           sum(u.link_clicks) AS link_clicks,
           sum(u.meta_purchases) AS meta_purchases,
           sum(u.meta_revenue) AS meta_revenue,
           CASE WHEN bool_or(u.is_up) THEN sum(u.up_nc) END AS upstack_new_customers,
           CASE WHEN bool_or(u.is_up) THEN sum(u.up_nc_rev) END AS upstack_new_customer_revenue,
           CASE WHEN bool_or(u.is_up) THEN sum(u.up_orders) END AS upstack_orders,
           CASE WHEN bool_or(u.is_up) THEN sum(u.up_rev) END AS upstack_order_revenue
    FROM (
        SELECT d.day, d.ad_id, d.source, false AS is_up, d.spend, d.impressions, d.link_clicks, d.purchases AS meta_purchases, d.conv_value AS meta_revenue,
               0::numeric AS up_nc, 0::numeric AS up_nc_rev, 0::numeric AS up_orders, 0::numeric AS up_rev
        FROM public.ad_daily d
        UNION ALL
        SELECT s.day, s.ad_id, NULL::text, true, 0::numeric, NULL::numeric, 0::numeric, 0::numeric, 0::numeric,
               s.nc_purchases, s.nc_conv_value, s.purchases, s.conv_value
        FROM public.ad_daily_upstack s
    ) u
    GROUP BY u.day, u.ad_id
) k
LEFT JOIN analytics.meta_ads a ON a.ad_id = k.ad_id;

-- Ad set x day: meta_ad_daily summed by ad set.
CREATE OR REPLACE VIEW analytics.meta_adset_daily AS
SELECT d.day,
       d.adset_id,
       max(d.adset_name) AS adset_name,
       max(d.campaign_id) AS campaign_id,
       max(d.campaign_name) AS campaign_name,
       max(d.stage) AS stage,
       max(d.account) AS account,
       count(DISTINCT d.ad_id) FILTER (WHERE d.spend > 0) AS ads_with_spend,
       sum(d.spend) AS spend,
       sum(d.impressions) AS impressions,
       sum(d.link_clicks) AS link_clicks,
       sum(d.meta_purchases) AS meta_purchases,
       sum(d.meta_revenue) AS meta_revenue,
       sum(d.upstack_new_customers) AS upstack_new_customers,
       sum(d.upstack_new_customer_revenue) AS upstack_new_customer_revenue,
       sum(d.upstack_orders) AS upstack_orders,
       sum(d.upstack_order_revenue) AS upstack_order_revenue
FROM analytics.meta_ad_daily d
GROUP BY d.day, d.adset_id;

-- Campaign x day: meta_ad_daily summed by campaign.
CREATE OR REPLACE VIEW analytics.meta_campaign_daily AS
SELECT d.day,
       d.campaign_id,
       max(d.campaign_name) AS campaign_name,
       max(d.stage) AS stage,
       max(d.account) AS account,
       count(DISTINCT d.adset_id) FILTER (WHERE d.spend > 0) AS adsets_with_spend,
       count(DISTINCT d.ad_id) FILTER (WHERE d.spend > 0) AS ads_with_spend,
       sum(d.spend) AS spend,
       sum(d.impressions) AS impressions,
       sum(d.link_clicks) AS link_clicks,
       sum(d.meta_purchases) AS meta_purchases,
       sum(d.meta_revenue) AS meta_revenue,
       sum(d.upstack_new_customers) AS upstack_new_customers,
       sum(d.upstack_new_customer_revenue) AS upstack_new_customer_revenue,
       sum(d.upstack_orders) AS upstack_orders,
       sum(d.upstack_order_revenue) AS upstack_order_revenue
FROM analytics.meta_ad_daily d
GROUP BY d.day, d.campaign_id;

-- ---------------------------------------------------------------------------------------------------------------- Google
-- Google campaign x day (Upstack channel feed + Upstack any-click attribution joined by campaign name). Google has no ad group / ad / keyword grain.
-- upstack_* is NULL on days before Upstack's Google attribution was pulled (2025-05-13), never 0.
CREATE OR REPLACE VIEW analytics.google_campaign_daily AS
SELECT g.day,
       g.campaign_key,
       g.campaign_name,
       g.campaign_type,
       gc.status AS campaign_status,
       gc.bid_strategy,
       g.in_feed,
       g.spend,
       g.impressions,
       g.clicks,
       g.purchases AS google_purchases,
       g.purchases_value AS google_revenue,
       CASE WHEN ud.day IS NOT NULL THEN g.nc END AS upstack_new_customers,
       CASE WHEN ud.day IS NOT NULL THEN g.nc_rev END AS upstack_new_customer_revenue,
       CASE WHEN ud.day IS NOT NULL THEN g.orders END AS upstack_orders,
       CASE WHEN ud.day IS NOT NULL THEN g.rev END AS upstack_order_revenue
FROM public.google_daily g
LEFT JOIN public.upstack_google_days ud ON ud.day = g.day
LEFT JOIN public.upstack_google_campaigns gc ON gc.campaign_id = g.campaign_key;

-- ---------------------------------------------------------------------------------------------------------------- platforms and orders
-- Platform x day for Meta and Google. spend is additive across platforms; purchases / revenue are NOT (both platforms credit the same orders).
-- Meta clicks = link clicks, Google clicks = all clicks.
CREATE OR REPLACE VIEW analytics.platform_daily AS
SELECT m.day,
       'meta'::text AS platform,
       sum(m.spend) AS spend,
       sum(m.impressions) AS impressions,
       sum(m.link_clicks) AS clicks,
       sum(m.meta_purchases) AS own_purchases,
       sum(m.meta_revenue) AS own_revenue,
       sum(m.upstack_new_customers) AS upstack_new_customers,
       sum(m.upstack_new_customer_revenue) AS upstack_new_customer_revenue,
       sum(m.upstack_orders) AS upstack_orders,
       sum(m.upstack_order_revenue) AS upstack_order_revenue
FROM analytics.meta_ad_daily m
GROUP BY m.day
UNION ALL
SELECT g.day,
       'google'::text,
       sum(g.spend),
       sum(g.impressions),
       sum(g.clicks),
       sum(g.google_purchases),
       sum(g.google_revenue),
       sum(g.upstack_new_customers),
       sum(g.upstack_new_customer_revenue),
       sum(g.upstack_orders),
       sum(g.upstack_order_revenue)
FROM analytics.google_campaign_daily g
GROUP BY g.day;

-- The business's actual revenue per Pacific day, counted once (Upstack order-level measures). new_customer_revenue is the numerator of Total NC ROAS.
CREATE OR REPLACE VIEW analytics.orders_daily AS
SELECT o.day,
       o.nc_rev    AS new_customer_revenue,
       o.nc_orders AS new_customers,
       o.rc_rev    AS returning_customer_revenue,
       o.total_rev AS total_revenue,
       o.orders,
       o.pulled_at AS loaded_at
FROM public.upstack_orders_daily o;

-- ---------------------------------------------------------------------------------------------------------------- creative tracker
-- One row per live tracker row (soft-deleted rows are left out) with its CURRENT tag in the product's own tag set, its hook and its since-launch
-- Meta-reported metrics. Metrics sit on the FIRST tracker row of each ad family only (the other rows of the family read 0), so SUM over rows is right
-- and a per-row average is wrong.
CREATE OR REPLACE VIEW analytics.creative_tracker AS
SELECT t.id AS tracker_row_id,
       t.row_key,
       p.slug AS product_slug,
       p.name AS product_name,
       t.concept_id,
       t.ad_family,
       t.family_key,
       t.status,
       t.ad_type,
       t.style,
       t.vendor,
       t.fidelity,
       t.proof,
       t.launch_date,
       t.concept_name,
       t.description,
       t.hypothesis,
       t.meta_ad_name,
       t.primary_text,
       t.headlines,
       t.ad_description,
       t.transcript,
       t.asset_url,
       t.tracker_cluster,
       t.tracker_icp,
       t.tracker_pain,
       t.tracker_emotion,
       t.tracker_ingredient,
       g.tag_set,
       g.version AS tag_version,
       tl.line_code,
       g.cluster,
       g.icp,
       g.pain_point,
       g.emotional_trigger,
       g.confidence AS tag_confidence,
       g.method AS tag_method,
       h.hook,
       h.hook_source,
       m.is_first_row,
       m.spend_launch,
       m.purchases_launch,
       m.revenue_launch,
       m.spend_7d,
       m.spend_30d,
       m.purchases_30d,
       m.revenue_30d,
       m.live,
       m.ads_active_count
FROM public.tracker_rows t
JOIN public.products p ON p.id = t.product_id
LEFT JOIN public.ad_tags g ON g.tracker_row_id = t.id AND g.is_current AND g.tag_set = p.tag_set
LEFT JOIN public.taxonomy_lines tl ON tl.id = g.line_id
LEFT JOIN public.ad_hooks h ON h.tracker_row_id = t.id
LEFT JOIN public.ad_metrics m ON m.tracker_row_id = t.id
WHERE t.deleted_at IS NULL;

-- ---------------------------------------------------------------------------------------------------------------- pipeline log
CREATE OR REPLACE VIEW analytics.etl_runs AS
SELECT r.id,
       r.job,
       r.started_at,
       r.finished_at,
       r.status,
       r.data_through,
       r.rows_written,
       r.stats,
       left(r.error, 500) AS error
FROM public.etl_runs r;

-- ---------------------------------------------------------------- comments
COMMENT ON SCHEMA analytics IS 'Read-only views over Lonvera''s marketing data (Meta, Google, Upstack attribution, actual orders, creative tracker). Start with data_coverage (what is loaded through which day) and read docs/AGENT_DATA_GUIDE.md. Rules: (1) name the basis: meta_* = Meta-reported, upstack_new_customer* = Upstack first orders (NC), upstack_order* = all Upstack-credited orders; (2) spend adds across Meta and Google, purchases and revenue never do; Total NC ROAS = orders_daily.new_customer_revenue / total spend of the same days; (3) the last loaded day is yesterday Pacific and the last 3-7 days still move; (4) upstack_* is NULL, not 0, on days Upstack was not pulled; (5) ratios from sums; creative_tracker metrics sit on the first row of each ad family.';
COMMENT ON VIEW analytics.meta_ads IS 'Dimension: one row per Meta ad (every ad the pipeline has ever seen: 42K, most ARCHIVED or DELETED) with its campaign, ad set, product, status and all-time totals. Join to the daily views on ad_id (they already carry the main names). Grain: one row per Meta ad_id. Source: public.meta_ads + meta_campaigns + meta_family_map + the product rule below + meta_ad_lifetime. Refresh: nightly (etl service 13:00 UTC): ad names, campaigns and totals from the Meta Graph API, status refreshed every night. Coverage: every ad with delivery since 2026-05-06 plus every ad the all-time pull returned; first_day / last_day only for ads that delivered since 2026-05-06. Caveats: product_slug follows the Products table: a Meta family that maps to a tracker family counts under the product of that family''s FIRST tracker row; a family off the tracker keeps the product guessed from its name, then campaign, then ad set; NULL = no active product. About 12K Meta families are on no tracker row. | family_key is the lower-cased ad name with '' - Copy N'' and merge-tag suffixes stripped: copies of one ad share a family. | lifetime_* are Meta-reported all-time totals through the last complete day (Graph insights, both accounts, replaced nightly). They cover the whole life of the ad, not just 2026-05-06 onward; the daily views start on 2026-05-06. | status is Meta''s effective_status; CAMPAIGN_PAUSED and ADSET_PAUSED mean the ad itself is on but a parent is off.';
COMMENT ON COLUMN analytics.meta_ads.ad_id IS 'Meta ad id (text, as Meta returns it).';
COMMENT ON COLUMN analytics.meta_ads.account IS 'Ad account name: ''Lonvera Main'' (America/Los_Angeles) or ''Lonvera BackUp'' (America/New_York).';
COMMENT ON COLUMN analytics.meta_ads.ad_name IS 'Current ad name in Meta (renames move the whole history).';
COMMENT ON COLUMN analytics.meta_ads.family_name IS 'Ad name without '' - Copy N'' / merge-tag suffixes, original case: the ad family.';
COMMENT ON COLUMN analytics.meta_ads.family_key IS 'Lower-cased family_name. The join key to the creative tracker side (meta_family_map).';
COMMENT ON COLUMN analytics.meta_ads.tracker_family_key IS 'Creative-tracker family this Meta family was matched to by the resolver (NULL = no tracker row). Joins creative_tracker.family_key.';
COMMENT ON COLUMN analytics.meta_ads.product_slug IS 'vita-bull | beef-liver | boneflex | vita-belle | vital-flow | unassigned, by the rule in the view description; NULL = no active product.';
COMMENT ON COLUMN analytics.meta_ads.product_name IS 'Display name of product_slug.';
COMMENT ON COLUMN analytics.meta_ads.campaign_id IS 'Meta campaign id.';
COMMENT ON COLUMN analytics.meta_ads.campaign_name IS 'Campaign name. A name containing ''test'' makes the campaign a testing campaign.';
COMMENT ON COLUMN analytics.meta_ads.stage IS '''testing'' when the campaign name contains ''test'' (case-insensitive), else ''scaling''. A naming rule, not a Meta field.';
COMMENT ON COLUMN analytics.meta_ads.adset_id IS 'Meta ad set id.';
COMMENT ON COLUMN analytics.meta_ads.adset_name IS 'Ad set name.';
COMMENT ON COLUMN analytics.meta_ads.status IS 'Meta effective_status: ACTIVE, PAUSED, CAMPAIGN_PAUSED, ADSET_PAUSED, ARCHIVED, DELETED, DISAPPROVED, WITH_ISSUES.';
COMMENT ON COLUMN analytics.meta_ads.is_active IS 'status = ''ACTIVE'' (the ad is eligible to deliver; it may still have spent nothing yet).';
COMMENT ON COLUMN analytics.meta_ads.created_date IS 'Pacific calendar date the ad was created.';
COMMENT ON COLUMN analytics.meta_ads.first_day IS 'First day with an ad_daily row (>= 2026-05-06); NULL for ads that never delivered in that window.';
COMMENT ON COLUMN analytics.meta_ads.last_day IS 'Last day with an ad_daily row.';
COMMENT ON COLUMN analytics.meta_ads.lifetime_spend IS 'All-time spend, dollars (Meta-reported). NULL when the ad has no lifetime row.';
COMMENT ON COLUMN analytics.meta_ads.lifetime_impressions IS 'All-time impressions.';
COMMENT ON COLUMN analytics.meta_ads.lifetime_link_clicks IS 'All-time link clicks (Meta ''link_click'').';
COMMENT ON COLUMN analytics.meta_ads.lifetime_purchases IS 'All-time Meta-reported purchases.';
COMMENT ON COLUMN analytics.meta_ads.lifetime_revenue IS 'All-time Meta-reported purchase conversion value, dollars.';
COMMENT ON VIEW analytics.meta_ad_daily IS 'The main Meta fact view: one row per Meta ad per day with Meta-reported results AND Upstack-attributed new customers / orders side by side, plus the ad''s names, campaign, ad set, stage and product. Roll up from here; never add purchases to Google''s. Grain: one row per (day, ad_id). Source: public.ad_daily (Meta Graph API, ad x day) combined per ad and day with public.ad_daily_upstack (Upstack any-click 30-day attribution mapped to ads), names from analytics.meta_ads. Refresh: nightly (etl service 13:00 UTC): Meta trailing 28 days re-pulled and replaced (Meta restates conversions for weeks), Upstack trailing 7 days re-pulled. Coverage: 2026-05-06 through yesterday (Pacific). Meta days are each ad account''s own calendar day; Upstack days are Pacific.. Caveats: Three bases live in this view. spend, impressions, link_clicks, meta_purchases, meta_revenue are Meta''s. upstack_new_customers / upstack_new_customer_revenue are Upstack''s first-order basis (the ''NC'' numbers: NC ROAS = upstack_new_customer_revenue / spend). upstack_orders / upstack_order_revenue are every order Upstack credits to the ad. Spend is Meta''s in all three. | upstack_* is NULL (not 0) on days Upstack has not been pulled; coverage starts 2026-05-06 as well. | Upstack credits an order to every ad clicked in the 30 days before it (any-click), so Upstack-only ad-days exist where the ad spent nothing that day (spend = 0, meta_* = 0, upstack_* > 0). Filter spend > 0 only if you want delivery days. | When one ad is copied into several ad sets under the same name, Upstack (which sees names, not ids) credit is split across the copies by their Meta spend that day. Family-level and higher sums are exact; one copy''s own upstack_* numbers are an allocation. | About 1.3% of Upstack-credited orders and 1.3% of new customers match no Meta ad (''(not set)'', deleted ads); they are in orders_daily but in no row here. | Meta purchases count returning customers; Upstack new customers do not. They are different quantities, not the same number measured twice. | link_clicks is Meta''s ''link_click'' action count (link clicks, not all clicks). Impressions are Meta''s. | source: ''meta_api'' for Graph-pulled rows, ''sheet'' for the old family-grain backfill (none left in production), NULL on Upstack-only ad-days.';
COMMENT ON COLUMN analytics.meta_ad_daily.day IS 'Calendar day. Meta numbers: the ad account''s own day (Main = America/Los_Angeles, BackUp = America/New_York, not re-based). Upstack numbers: Pacific.';
COMMENT ON COLUMN analytics.meta_ad_daily.ad_id IS 'Meta ad id.';
COMMENT ON COLUMN analytics.meta_ad_daily.ad_name IS 'Current ad name.';
COMMENT ON COLUMN analytics.meta_ad_daily.product_slug IS 'Product the ad counts under (see analytics.meta_ads); NULL = no active product.';
COMMENT ON COLUMN analytics.meta_ad_daily.campaign_id IS 'Meta campaign id (NULL on family-grain legacy rows).';
COMMENT ON COLUMN analytics.meta_ad_daily.campaign_name IS 'Campaign name.';
COMMENT ON COLUMN analytics.meta_ad_daily.stage IS '''testing'' | ''scaling'' from the campaign name (''test'' in the name = testing).';
COMMENT ON COLUMN analytics.meta_ad_daily.adset_id IS 'Meta ad set id (NULL on family-grain legacy rows).';
COMMENT ON COLUMN analytics.meta_ad_daily.adset_name IS 'Ad set name.';
COMMENT ON COLUMN analytics.meta_ad_daily.account IS '''Lonvera Main'' or ''Lonvera BackUp''.';
COMMENT ON COLUMN analytics.meta_ad_daily.source IS 'Where the Meta side of the row came from: ''meta_api'' | ''sheet''; NULL when the row exists only because Upstack credited the ad.';
COMMENT ON COLUMN analytics.meta_ad_daily.spend IS 'Meta spend, dollars (0 on Upstack-only ad-days). Additive across ads, ad sets, campaigns and across platforms.';
COMMENT ON COLUMN analytics.meta_ad_daily.impressions IS 'Meta impressions.';
COMMENT ON COLUMN analytics.meta_ad_daily.link_clicks IS 'Meta link clicks.';
COMMENT ON COLUMN analytics.meta_ad_daily.meta_purchases IS 'Purchases Meta reports for the ad that day (omni_purchase, else purchase, else pixel purchase), Meta''s default attribution; includes returning customers.';
COMMENT ON COLUMN analytics.meta_ad_daily.meta_revenue IS 'Purchase conversion value Meta reports, dollars. meta_revenue / spend = Meta ROAS.';
COMMENT ON COLUMN analytics.meta_ad_daily.upstack_new_customers IS 'First-time customers Upstack credits to the ad (any-click, 30-day window, utm_source ''Meta Ads''). NULL on days not pulled.';
COMMENT ON COLUMN analytics.meta_ad_daily.upstack_new_customer_revenue IS 'Order total (tax included, before refunds) of those first orders, dollars. / spend = NC ROAS.';
COMMENT ON COLUMN analytics.meta_ad_daily.upstack_orders IS 'All orders (new and returning customers) Upstack credits to the ad. NULL on days not pulled.';
COMMENT ON COLUMN analytics.meta_ad_daily.upstack_order_revenue IS 'Order total of those orders, dollars (tax included, before refunds).';
COMMENT ON VIEW analytics.meta_adset_daily IS 'Ad set x day roll-up of meta_ad_daily (Meta-reported and Upstack bases side by side). Grain: one row per (day, adset_id). Source: analytics.meta_ad_daily grouped by day and ad set. Refresh: same as meta_ad_daily. Coverage: 2026-05-06 through yesterday. Caveats: Same bases and NULL rules as meta_ad_daily. adset_id is NULL only for legacy family-grain rows (none in production). | An ad set belongs to one campaign; names are the current ones. There is no product column because an ad set can hold ads of several products: group meta_ad_daily by product_slug instead.';
COMMENT ON COLUMN analytics.meta_adset_daily.day IS 'Calendar day (see meta_ad_daily).';
COMMENT ON COLUMN analytics.meta_adset_daily.adset_id IS 'Meta ad set id.';
COMMENT ON COLUMN analytics.meta_adset_daily.adset_name IS 'Ad set name.';
COMMENT ON COLUMN analytics.meta_adset_daily.campaign_id IS 'Parent campaign id.';
COMMENT ON COLUMN analytics.meta_adset_daily.campaign_name IS 'Parent campaign name.';
COMMENT ON COLUMN analytics.meta_adset_daily.stage IS '''testing'' | ''scaling'' from the campaign name.';
COMMENT ON COLUMN analytics.meta_adset_daily.account IS '''Lonvera Main'' or ''Lonvera BackUp''.';
COMMENT ON COLUMN analytics.meta_adset_daily.ads_with_spend IS 'Distinct ads in the ad set with spend > 0 that day.';
COMMENT ON COLUMN analytics.meta_adset_daily.spend IS 'Meta spend, dollars.';
COMMENT ON COLUMN analytics.meta_adset_daily.impressions IS 'Meta impressions.';
COMMENT ON COLUMN analytics.meta_adset_daily.link_clicks IS 'Meta link clicks.';
COMMENT ON COLUMN analytics.meta_adset_daily.meta_purchases IS 'Meta-reported purchases.';
COMMENT ON COLUMN analytics.meta_adset_daily.meta_revenue IS 'Meta-reported purchase value, dollars.';
COMMENT ON COLUMN analytics.meta_adset_daily.upstack_new_customers IS 'Upstack first-time customers credited to the ad set''s ads (NULL on days not pulled).';
COMMENT ON COLUMN analytics.meta_adset_daily.upstack_new_customer_revenue IS 'Their first-order revenue, dollars.';
COMMENT ON COLUMN analytics.meta_adset_daily.upstack_orders IS 'All Upstack-credited orders.';
COMMENT ON COLUMN analytics.meta_adset_daily.upstack_order_revenue IS 'Revenue of those orders, dollars.';
COMMENT ON VIEW analytics.meta_campaign_daily IS 'Campaign x day roll-up of meta_ad_daily (Meta-reported and Upstack bases side by side). Grain: one row per (day, campaign_id). Source: analytics.meta_ad_daily grouped by day and campaign. Refresh: same as meta_ad_daily. Coverage: 2026-05-06 through yesterday (use meta_campaign_daily_history for campaign-level days back to 2024-12-31). Caveats: Same bases and NULL rules as meta_ad_daily. | A campaign can run ads of several products (shared All_US / test campaigns): split by product with meta_ad_daily.';
COMMENT ON COLUMN analytics.meta_campaign_daily.day IS 'Calendar day (see meta_ad_daily).';
COMMENT ON COLUMN analytics.meta_campaign_daily.campaign_id IS 'Meta campaign id.';
COMMENT ON COLUMN analytics.meta_campaign_daily.campaign_name IS 'Campaign name.';
COMMENT ON COLUMN analytics.meta_campaign_daily.stage IS '''testing'' | ''scaling'' from the campaign name.';
COMMENT ON COLUMN analytics.meta_campaign_daily.account IS '''Lonvera Main'' or ''Lonvera BackUp''.';
COMMENT ON COLUMN analytics.meta_campaign_daily.adsets_with_spend IS 'Distinct ad sets with spend > 0 that day.';
COMMENT ON COLUMN analytics.meta_campaign_daily.ads_with_spend IS 'Distinct ads with spend > 0 that day.';
COMMENT ON COLUMN analytics.meta_campaign_daily.spend IS 'Meta spend, dollars.';
COMMENT ON COLUMN analytics.meta_campaign_daily.impressions IS 'Meta impressions.';
COMMENT ON COLUMN analytics.meta_campaign_daily.link_clicks IS 'Meta link clicks.';
COMMENT ON COLUMN analytics.meta_campaign_daily.meta_purchases IS 'Meta-reported purchases.';
COMMENT ON COLUMN analytics.meta_campaign_daily.meta_revenue IS 'Meta-reported purchase value, dollars.';
COMMENT ON COLUMN analytics.meta_campaign_daily.upstack_new_customers IS 'Upstack first-time customers credited to the campaign''s ads (NULL on days not pulled).';
COMMENT ON COLUMN analytics.meta_campaign_daily.upstack_new_customer_revenue IS 'Their first-order revenue, dollars.';
COMMENT ON COLUMN analytics.meta_campaign_daily.upstack_orders IS 'All Upstack-credited orders.';
COMMENT ON COLUMN analytics.meta_campaign_daily.upstack_order_revenue IS 'Revenue of those orders, dollars.';
COMMENT ON VIEW analytics.google_campaign_daily IS 'Google Ads campaign x day: Google''s own spend, impressions, clicks and conversions plus Upstack''s attributed new customers / orders. Google has no ad group, ad or keyword grain in this database. Grain: one row per (day, campaign_key). Source: public.google_daily (Upstack channel feed joined to Upstack any-click 30-day attribution by campaign name) + upstack_google_campaigns. Refresh: nightly (etl service 13:00 UTC): trailing 7 days re-pulled; the job refuses a day with more than $200 spend and no attributed orders. Coverage: Google''s own numbers 2024-03-25 through yesterday (Pacific); Upstack columns from 2025-05-13 (NULL before). Caveats: Two bases: google_* are Google''s own conversions (restated by Google for days afterwards); upstack_* are Upstack''s attribution of orders to the campaign (utm campaign name), any-click 30-day, which credits Google with orders that also had a Meta click. | Purchases and revenue overlap with Meta''s: never add google_* or upstack_* to Meta''s. Spend, impressions and clicks are additive. | campaign_type is read from the campaign NAME (Shopping, Search, Performance Max, Demand Gen, Other); Upstack exposes none. ''Other'' is never guessed. | in_feed = false rows are Upstack-attributed orders whose utm campaign matches no Google campaign (''(not set)'', raw ids, deleted campaigns): spend 0, kept so totals tie to Upstack''s Google total (about 3% of orders). | clicks are all clicks (Google has no link-click event).';
COMMENT ON COLUMN analytics.google_campaign_daily.day IS 'Pacific day (Upstack buckets by America/Los_Angeles).';
COMMENT ON COLUMN analytics.google_campaign_daily.campaign_key IS 'Google campaign id, or ''name:<utm campaign>'' when the utm value is no Google campaign (in_feed = false).';
COMMENT ON COLUMN analytics.google_campaign_daily.campaign_name IS 'Campaign name.';
COMMENT ON COLUMN analytics.google_campaign_daily.campaign_type IS 'Shopping | Search | Performance Max | Demand Gen | Other, read from the name.';
COMMENT ON COLUMN analytics.google_campaign_daily.campaign_status IS 'Campaign status from the Upstack feed (NULL for in_feed = false rows).';
COMMENT ON COLUMN analytics.google_campaign_daily.bid_strategy IS 'Bid strategy from the Upstack feed (NULL for in_feed = false rows).';
COMMENT ON COLUMN analytics.google_campaign_daily.in_feed IS 'true = a Google campaign in the channel feed; false = utm campaign with no Google campaign.';
COMMENT ON COLUMN analytics.google_campaign_daily.spend IS 'Google spend, dollars.';
COMMENT ON COLUMN analytics.google_campaign_daily.impressions IS 'Google impressions.';
COMMENT ON COLUMN analytics.google_campaign_daily.clicks IS 'Google clicks (all clicks).';
COMMENT ON COLUMN analytics.google_campaign_daily.google_purchases IS 'Purchases Google reports (delivered through Upstack''s ad-platform feed).';
COMMENT ON COLUMN analytics.google_campaign_daily.google_revenue IS 'Conversion value Google reports, dollars.';
COMMENT ON COLUMN analytics.google_campaign_daily.upstack_new_customers IS 'First-time customers Upstack credits to the campaign (any-click, 30 days, utm_source ''Google Ads''). NULL before 2025-05-13.';
COMMENT ON COLUMN analytics.google_campaign_daily.upstack_new_customer_revenue IS 'Their first-order revenue, dollars (tax included, before refunds).';
COMMENT ON COLUMN analytics.google_campaign_daily.upstack_orders IS 'All orders Upstack credits to the campaign.';
COMMENT ON COLUMN analytics.google_campaign_daily.upstack_order_revenue IS 'Revenue of those orders, dollars.';
COMMENT ON VIEW analytics.platform_daily IS 'Meta and Google side by side per day. Spend, impressions and clicks are additive across the two platforms; purchases and revenue are not. Grain: one row per (day, platform) with platform ''meta'' or ''google''. Source: analytics.meta_ad_daily and analytics.google_campaign_daily grouped by day. Refresh: nightly (etl service 13:00 UTC). Coverage: Meta 2026-05-06.., Google 2024-03-25.. through yesterday (Pacific); Total NC ROAS is defined only on days both platforms and orders_daily have. Caveats: spend is additive: Total spend = sum over platforms. own_purchases / own_revenue / upstack_* are NOT: both platforms credit the same orders (the overlap cannot be measured), so adding them gives the wrong number. Never divide a sum of platform revenue by total spend. | Total NC ROAS = actual new-customer revenue (analytics.orders_daily.new_customer_revenue, counted once) / total spend of the same days. Use the example below. | clicks: Meta = link clicks, Google = all clicks. own_* is each platform''s own reporting; upstack_* is Upstack''s any-click 30-day attribution. | Meta days are each ad account''s own day, Google and Upstack days are Pacific; the one-day offset matters only for the BackUp account (New York).';
COMMENT ON COLUMN analytics.platform_daily.day IS 'Calendar day (Meta: ad account day; Google / Upstack: Pacific).';
COMMENT ON COLUMN analytics.platform_daily.platform IS '''meta'' | ''google''.';
COMMENT ON COLUMN analytics.platform_daily.spend IS 'Platform spend, dollars. Additive across platforms.';
COMMENT ON COLUMN analytics.platform_daily.impressions IS 'Platform impressions.';
COMMENT ON COLUMN analytics.platform_daily.clicks IS 'Meta: link clicks. Google: all clicks.';
COMMENT ON COLUMN analytics.platform_daily.own_purchases IS 'Purchases the platform reports itself. Not additive across platforms.';
COMMENT ON COLUMN analytics.platform_daily.own_revenue IS 'Conversion value the platform reports itself, dollars. Not additive across platforms.';
COMMENT ON COLUMN analytics.platform_daily.upstack_new_customers IS 'Upstack first-time customers credited to the platform (NULL on days Upstack was not pulled). Not additive across platforms.';
COMMENT ON COLUMN analytics.platform_daily.upstack_new_customer_revenue IS 'Their first-order revenue, dollars. Not additive across platforms.';
COMMENT ON COLUMN analytics.platform_daily.upstack_orders IS 'All orders Upstack credits to the platform. Not additive across platforms.';
COMMENT ON COLUMN analytics.platform_daily.upstack_order_revenue IS 'Revenue of those orders, dollars. Not additive across platforms.';
COMMENT ON VIEW analytics.orders_daily IS 'The business''s ACTUAL revenue and customers per Pacific day, counted once (Upstack order-level measures). new_customer_revenue is the numerator of Total NC ROAS. Grain: one row per Pacific day with orders. Source: public.upstack_orders_daily (Upstack /api/query, orders.* measures, America/Los_Angeles). Refresh: nightly (etl service 13:00 UTC): trailing 7 days replaced because Upstack restates recent days. Coverage: 2025-01-01 through yesterday (Pacific). Caveats: Revenue is the order total as Upstack reports it (tax included), before refunds: all numbers are gross. | There is no product, platform or campaign dimension: you cannot split new-customer revenue by product here. Use the attributed columns of the Meta / Google views (an attribution, not the actual) or the sheet''s NC Rev - By Product (proj_feed_nc_product, sheet-fed, not in analytics). | A day with no orders is absent, not zero. | new_customers is the count of first-time customers (first orders).';
COMMENT ON COLUMN analytics.orders_daily.day IS 'Pacific day.';
COMMENT ON COLUMN analytics.orders_daily.new_customer_revenue IS 'Revenue of first orders that day, dollars (tax included, before refunds). orders.new_customer_total_revenue.';
COMMENT ON COLUMN analytics.orders_daily.new_customers IS 'Number of new customers (first orders) that day. orders.new_customers.';
COMMENT ON COLUMN analytics.orders_daily.returning_customer_revenue IS 'Revenue of repeat orders, dollars (subscription rebills included). orders.returning_customer_total_revenue.';
COMMENT ON COLUMN analytics.orders_daily.total_revenue IS 'new + returning revenue, dollars. orders.total_revenue.';
COMMENT ON COLUMN analytics.orders_daily.orders IS 'All orders that day (new and returning). orders.count.';
COMMENT ON COLUMN analytics.orders_daily.loaded_at IS 'When the day was last (re)pulled from Upstack.';
COMMENT ON VIEW analytics.creative_tracker IS 'One row per live Creative Tracker row (a concept / ad variant) with its current tag in the product''s own tag set, its hook and its since-launch Meta-reported metrics. The way to ask ''which cluster / ICP / pain point / hook performs''. Grain: one row per tracker row (tracker_row_id); an ''ad family'' (family_key) can span several rows. Source: public.tracker_rows + ad_tags (current) + taxonomy_lines + ad_hooks + ad_metrics + products. Refresh: tracker rows synced nightly from the Creative Key Google Sheet (etl service 13:00 UTC); linemap tags and hooks are loaded by hand per tagging cycle (versions dated 2026-11-03 to 2026-11-05). Coverage: all live tracker rows (~3,980); soft-deleted rows are left out. Caveats: Metrics (spend_launch ... ads_active_count) sit on the FIRST tracker row of each ad family only; the other rows of the family read 0 (is_first_row says which). So sum over rows is right and a per-row average is wrong. ''Unique ads'' = count of distinct family_key. | Since-launch metrics are Meta-reported (Graph API all-time per ad, summed over the family''s Meta ads), not Upstack. spend_7d / _30d end on the last complete day. | Tags: products.tag_set decides which set drives the hierarchy: ''linemap'' (cluster / ICP / pain point / trigger of the Communication Overview line, read from the creative image or video by a tagger, with a confidence) for Vita Bull, Beef Liver and Boneflex; ''tracker'' (the tracker''s own columns) for the rest. The tracker_* columns are always the tracker''s own tags. A row with no current tag has NULL tag columns. | A family whose tracker rows carry different tags appears under each of them; its spend counts only where its first row sits. | asset_url is a Google Drive link to the creative file; access to the file is governed by Drive, not by this database.';
COMMENT ON COLUMN analytics.creative_tracker.tracker_row_id IS 'Primary key (tracker_rows.id).';
COMMENT ON COLUMN analytics.creative_tracker.row_key IS 'Stable row key: concept id + ''#'' + ordinal among rows sharing (concept id, ad family). Never a sheet row number.';
COMMENT ON COLUMN analytics.creative_tracker.product_slug IS 'vita-bull | beef-liver | boneflex | vita-belle | vital-flow | unassigned, from the tracker''s Product column.';
COMMENT ON COLUMN analytics.creative_tracker.product_name IS 'Display name of the product.';
COMMENT ON COLUMN analytics.creative_tracker.concept_id IS 'Tracker Concept ID (text: ''0510'' is not ''510'').';
COMMENT ON COLUMN analytics.creative_tracker.ad_family IS 'Tracker ''Ad Family'' as typed; empty when blank.';
COMMENT ON COLUMN analytics.creative_tracker.family_key IS 'lower(ad_family), or ''id:'' + lower(concept_id) when blank. The unique-ad key; joins analytics.meta_ads.tracker_family_key.';
COMMENT ON COLUMN analytics.creative_tracker.status IS 'Tracker status, e.g. ''8 - Launched'', ''5 - Creative In Progress'', ''3 - Briefing''.';
COMMENT ON COLUMN analytics.creative_tracker.ad_type IS 'VID (video) | IMG (image) | NULL.';
COMMENT ON COLUMN analytics.creative_tracker.style IS 'Creative style (tracker column).';
COMMENT ON COLUMN analytics.creative_tracker.vendor IS 'Who made it (tracker column), e.g. Madre, Victoria, Internal, 10xROAS.';
COMMENT ON COLUMN analytics.creative_tracker.fidelity IS 'Creative fidelity (tracker column).';
COMMENT ON COLUMN analytics.creative_tracker.proof IS 'Proof mechanism (tracker column).';
COMMENT ON COLUMN analytics.creative_tracker.launch_date IS 'Launch date from the tracker (a date typed by the team; NULL when blank).';
COMMENT ON COLUMN analytics.creative_tracker.concept_name IS 'Concept name.';
COMMENT ON COLUMN analytics.creative_tracker.description IS 'Short description.';
COMMENT ON COLUMN analytics.creative_tracker.hypothesis IS 'Why the team tested it.';
COMMENT ON COLUMN analytics.creative_tracker.meta_ad_name IS 'The ad name to look for in Meta (tracker ''Name'' column).';
COMMENT ON COLUMN analytics.creative_tracker.primary_text IS 'Ad primary texts (array, up to 3).';
COMMENT ON COLUMN analytics.creative_tracker.headlines IS 'Ad headlines (array, up to 3).';
COMMENT ON COLUMN analytics.creative_tracker.ad_description IS 'Ad description line.';
COMMENT ON COLUMN analytics.creative_tracker.transcript IS 'Video transcript from the tracker (can differ from the audio actually running; the linemap taggers re-transcribed top spenders).';
COMMENT ON COLUMN analytics.creative_tracker.asset_url IS 'Link to the creative asset (Google Drive).';
COMMENT ON COLUMN analytics.creative_tracker.tracker_cluster IS 'Tracker''s own Market Cluster.';
COMMENT ON COLUMN analytics.creative_tracker.tracker_icp IS 'Tracker''s own ICP (persona) column.';
COMMENT ON COLUMN analytics.creative_tracker.tracker_pain IS 'Tracker''s own Pain Point.';
COMMENT ON COLUMN analytics.creative_tracker.tracker_emotion IS 'Tracker''s own Emotion.';
COMMENT ON COLUMN analytics.creative_tracker.tracker_ingredient IS 'Tracker''s Lead Ingredient.';
COMMENT ON COLUMN analytics.creative_tracker.tag_set IS 'Which tag set the tag columns come from: ''linemap'' | ''tracker'' (products.tag_set); NULL when the row is untagged in that set.';
COMMENT ON COLUMN analytics.creative_tracker.tag_version IS 'Tagging cycle, e.g. ''linemap-v2-2026-11-03'', ''tracker-live''.';
COMMENT ON COLUMN analytics.creative_tracker.line_code IS 'Communication Overview line code (L01.. Vita Bull, B01.. Beef Liver, BF01.. Boneflex); NULL for tracker tags.';
COMMENT ON COLUMN analytics.creative_tracker.cluster IS 'Market cluster of the tag.';
COMMENT ON COLUMN analytics.creative_tracker.icp IS 'ICP / persona of the tag.';
COMMENT ON COLUMN analytics.creative_tracker.pain_point IS 'Pain point of the tag.';
COMMENT ON COLUMN analytics.creative_tracker.emotional_trigger IS 'Emotional trigger of the line (linemap tags).';
COMMENT ON COLUMN analytics.creative_tracker.tag_confidence IS 'high | medium | low (linemap tags): how sure the tagger was; agreement of a blind re-tag is stored in app_meta reliability:<product>.';
COMMENT ON COLUMN analytics.creative_tracker.tag_method IS 'How it was tagged: ''image'', ''video: 4 frames + Whisper transcript'', ''text only'', ''no picture (copy only)'', ''video: thumbnail + no audio'' ...';
COMMENT ON COLUMN analytics.creative_tracker.hook IS 'The ad''s hook: first spoken line plus on-image headline, one short line (NULL when none was readable).';
COMMENT ON COLUMN analytics.creative_tracker.hook_source IS 'spoken | on_screen | both | copy | none.';
COMMENT ON COLUMN analytics.creative_tracker.is_first_row IS 'true on the one row of the family that carries its metrics.';
COMMENT ON COLUMN analytics.creative_tracker.spend_launch IS 'Since-launch Meta spend of the family, dollars (first row only).';
COMMENT ON COLUMN analytics.creative_tracker.purchases_launch IS 'Since-launch Meta-reported purchases (first row only).';
COMMENT ON COLUMN analytics.creative_tracker.revenue_launch IS 'Since-launch Meta-reported purchase value, dollars (first row only).';
COMMENT ON COLUMN analytics.creative_tracker.spend_7d IS 'Spend over the 7 days ending the last complete day (first row only).';
COMMENT ON COLUMN analytics.creative_tracker.spend_30d IS 'Spend over the 30 days ending the last complete day (first row only).';
COMMENT ON COLUMN analytics.creative_tracker.purchases_30d IS 'Meta-reported purchases over the same 30 days (first row only).';
COMMENT ON COLUMN analytics.creative_tracker.revenue_30d IS 'Meta-reported purchase value over the same 30 days (first row only).';
COMMENT ON COLUMN analytics.creative_tracker.live IS 'true when the family spent on either of the last two days (first row only).';
COMMENT ON COLUMN analytics.creative_tracker.ads_active_count IS 'Meta ads of the family that are ACTIVE now (same value on every row of the family).';
COMMENT ON VIEW analytics.etl_runs IS 'Log of every pipeline job run (tracker sync, Meta pull, lifetime pull, status refresh, metrics build, Upstack pull, hook / tag loads). Check it when a number looks stale. Grain: one row per job run. Source: public.etl_runs (written by etl.db.JobRun on its own autocommit connection). Refresh: live, one row per run. Coverage: since the first production run (2026-11-04 UTC). Caveats: status is running | ok | failed. A run that crashed leaves ''running''. error is scrubbed of tokens and cut to 500 characters. | stats is job-specific JSON (counts, reconciliation, windows). data_through is set by jobs that load daily data.';
COMMENT ON COLUMN analytics.etl_runs.id IS 'Run id (monotonic).';
COMMENT ON COLUMN analytics.etl_runs.job IS 'Job name: run_daily, tracker_sync, meta_pull, lifetime_pull, status_refresh, build_metrics, upstack_daily, load_tags, load_hooks ...';
COMMENT ON COLUMN analytics.etl_runs.started_at IS 'Start time (UTC timestamptz).';
COMMENT ON COLUMN analytics.etl_runs.finished_at IS 'Finish time (NULL while running).';
COMMENT ON COLUMN analytics.etl_runs.status IS 'running | ok | failed.';
COMMENT ON COLUMN analytics.etl_runs.data_through IS 'Last data day the job covered (NULL for jobs without one).';
COMMENT ON COLUMN analytics.etl_runs.rows_written IS 'Rows the job wrote, when it counts them.';
COMMENT ON COLUMN analytics.etl_runs.stats IS 'Job-specific JSON.';
COMMENT ON COLUMN analytics.etl_runs.error IS 'Error text when failed (scrubbed, first 500 characters).';
COMMENT ON TABLE public.ad_daily IS 'Meta Graph API results per ad per day: the base fact table behind every Meta number. Meta-reported (Meta''s own attribution). Grain: one row per (ad_id, day). Source: Meta Graph API insights level=ad, time_increment=1, both ad accounts (Lonvera Main, Lonvera BackUp); written by etl.meta_pull. Refresh: nightly (etl service 13:00 UTC, etl.run_daily): the trailing 28 days are re-pulled and replaced in ONE transaction (all or nothing), because Meta restates conversions for weeks. Coverage: 2026-05-06 (app_meta.daily_start, never moves) through yesterday; about 135K rows, 18.7K distinct ads in production. Caveats: day is the ad account''s OWN calendar day (Main = America/Los_Angeles, BackUp = New York); not re-based. | purchases = Meta action omni_purchase, else purchase, else offsite_conversion.fb_pixel_purchase, under Meta''s default attribution (no window is requested); it counts returning customers. conv_value is the matching action value. Neither is Upstack''s new-customer number. | No row filter on spend: purchases booked on days without delivery are kept, so a row can have spend 0 and purchases > 0. | link_clicks is Meta''s link_click action (fallback inline_link_clicks). impressions is NULL only on legacy sheet rows (none in production). | meta_family_key / meta_family follow the ad''s CURRENT name (build_metrics re-syncs them after a rename). | Rows with source ''sheet'' / ad_id ''fam:<family>'' were a family-grain backfill; none remain in production. | Reach, frequency, video metrics (thruplays, watch time), demographic / placement breakdowns, ad-level budgets and bids are NOT stored.';
COMMENT ON COLUMN public.ad_daily.ad_id IS 'Meta ad id (text). ''fam:<family key>'' on legacy family-grain rows.';
COMMENT ON COLUMN public.ad_daily.day IS 'Calendar day in the ad account''s own timezone.';
COMMENT ON COLUMN public.ad_daily.meta_family_key IS 'lower(ad family): ad name without '' - Copy N'' / merge-tag suffixes. Joins meta_family_map.';
COMMENT ON COLUMN public.ad_daily.meta_family IS 'The ad family with its original case.';
COMMENT ON COLUMN public.ad_daily.campaign_id IS 'Meta campaign id ('''' = unknown, legacy rows only).';
COMMENT ON COLUMN public.ad_daily.spend IS 'Meta spend, dollars.';
COMMENT ON COLUMN public.ad_daily.purchases IS 'Meta-reported purchases (omni_purchase > purchase > pixel purchase), Meta default attribution; includes returning customers.';
COMMENT ON COLUMN public.ad_daily.conv_value IS 'Meta-reported purchase conversion value, dollars (revenue for Meta ROAS).';
COMMENT ON COLUMN public.ad_daily.link_clicks IS 'Meta link clicks.';
COMMENT ON COLUMN public.ad_daily.source IS '''meta_api'' | ''sheet''.';
COMMENT ON COLUMN public.ad_daily.loaded_at IS 'When the row was written.';
COMMENT ON COLUMN public.ad_daily.impressions IS 'Meta impressions (NULL = unknown, legacy rows).';
COMMENT ON TABLE public.meta_ads IS 'One row per Meta ad: name, family, campaign, ad set, status, creation time. The raw dimension behind analytics.meta_ads. Grain: one row per ad_id. Source: Meta Graph API: names and ids from the daily and all-time insights pulls, status / name / created_time from etl.status_refresh. Refresh: nightly (etl.run_daily); status is refreshed for every ad that delivered in the last 60 days and every ad not ARCHIVED / DELETED. Coverage: 42K ads: every ad in the daily window plus every ad the all-time pull returned. Caveats: first_day / last_day are the first / last ad_daily day of the ad (NULL for the ~23K ads that never delivered since 2026-05-06). | status is Meta''s effective_status at status_checked_at. | family_name / meta_family_key are fam(ad_name): '' - Copy N'' and '' | x-merge-DATE'' suffixes stripped.';
COMMENT ON COLUMN public.meta_ads.ad_id IS 'Meta ad id.';
COMMENT ON COLUMN public.meta_ads.account IS '''Lonvera Main'' | ''Lonvera BackUp''.';
COMMENT ON COLUMN public.meta_ads.ad_name IS 'Current ad name.';
COMMENT ON COLUMN public.meta_ads.meta_family_key IS 'lower(family_name). Joins meta_family_map.meta_family_key and ad_daily.meta_family_key.';
COMMENT ON COLUMN public.meta_ads.campaign_id IS 'Meta campaign id. Joins meta_campaigns.';
COMMENT ON COLUMN public.meta_ads.adset_id IS 'Meta ad set id.';
COMMENT ON COLUMN public.meta_ads.adset_name IS 'Ad set name.';
COMMENT ON COLUMN public.meta_ads.created_date IS 'Pacific calendar date of created_at.';
COMMENT ON COLUMN public.meta_ads.status IS 'Meta effective_status.';
COMMENT ON COLUMN public.meta_ads.first_day IS 'First ad_daily day for the ad.';
COMMENT ON COLUMN public.meta_ads.last_day IS 'Last ad_daily day for the ad.';
COMMENT ON COLUMN public.meta_ads.created_at IS 'Exact creation instant (UTC).';
COMMENT ON COLUMN public.meta_ads.family_name IS 'Ad name with copy / merge suffixes stripped, original case.';
COMMENT ON COLUMN public.meta_ads.status_checked_at IS 'When status was last read from Graph.';
COMMENT ON TABLE public.meta_campaigns IS 'One row per Meta campaign with its stage (testing / scaling). Stage is a naming rule applied on every pull. Grain: one row per campaign_id. Source: Meta Graph API campaign names seen in the daily and all-time pulls; stage recomputed by etl.build_metrics. Refresh: nightly (etl.run_daily). Coverage: 185 campaigns, 2026-05-06 onward. Caveats: stage = ''testing'' when lower(name) contains ''test'', else ''scaling''. It is a convention of the campaign naming, not a Meta setting. | first_day / last_day = first / last ad_daily day with spend rows for the campaign.';
COMMENT ON COLUMN public.meta_campaigns.campaign_id IS 'Meta campaign id (text).';
COMMENT ON COLUMN public.meta_campaigns.account IS 'Ad account name.';
COMMENT ON COLUMN public.meta_campaigns.name IS 'Campaign name.';
COMMENT ON COLUMN public.meta_campaigns.stage IS '''testing'' | ''scaling''.';
COMMENT ON COLUMN public.meta_campaigns.first_day IS 'First day with ad_daily rows.';
COMMENT ON COLUMN public.meta_campaigns.last_day IS 'Last day with ad_daily rows.';
COMMENT ON TABLE public.meta_ad_lifetime IS 'All-time Meta totals per ad (Meta-reported), the source of every ''since launch'' number. Grain: one row per ad_id. Source: Meta Graph API insights level=ad over the whole account life (etl.lifetime_pull), both accounts. Refresh: nightly (etl.run_daily): the table is REPLACED as a whole, only when both accounts reconcile with account-level lifetime spend within 0.5%. Coverage: 41.7K ads, through the last complete day. Caveats: Totals cover the ad''s whole life, which reaches back before ad_daily''s 2026-05-06 start. | tracker_family_key is only filled on legacy sheet-sourced rows; use meta_family_map for the tracker match. source is ''meta_api'' for every production row. | Meta-reported (default attribution); purchases include returning customers.';
COMMENT ON COLUMN public.meta_ad_lifetime.ad_id IS 'Meta ad id.';
COMMENT ON COLUMN public.meta_ad_lifetime.meta_family_key IS 'lower(ad family), re-synced to the ad''s current name.';
COMMENT ON COLUMN public.meta_ad_lifetime.tracker_family_key IS 'Legacy: the sheet tab''s Ad Family column (NULL for API rows).';
COMMENT ON COLUMN public.meta_ad_lifetime.spend IS 'All-time spend, dollars.';
COMMENT ON COLUMN public.meta_ad_lifetime.purchases IS 'All-time Meta-reported purchases.';
COMMENT ON COLUMN public.meta_ad_lifetime.conv_value IS 'All-time Meta-reported purchase value, dollars.';
COMMENT ON COLUMN public.meta_ad_lifetime.impressions IS 'All-time impressions.';
COMMENT ON COLUMN public.meta_ad_lifetime.link_clicks IS 'All-time link clicks.';
COMMENT ON COLUMN public.meta_ad_lifetime.source IS '''meta_api'' (production) | ''sheet'' (legacy).';
COMMENT ON COLUMN public.meta_ad_lifetime.pulled_at IS 'When the all-time pull ran.';
COMMENT ON COLUMN public.meta_ad_lifetime.first_day IS 'Earliest delivery day if known (legacy).';
COMMENT ON TABLE public.ad_lifetime IS 'LEGACY: the sheet-era lifetime snapshot per tracker family (through app_meta.lifetime_cutoff 2026-09-17). Superseded by meta_ad_lifetime; do not use for current numbers. Grain: one row per tracker family_key. Source: Creative Key sheet tab ''Meta Ads - Lifetime'' (frozen snapshot loaded once at backfill). Refresh: never (frozen). Coverage: through 2026-09-17. Caveats: Kept for history only; since-launch figures now come from meta_ad_lifetime via meta_family_map.';
COMMENT ON COLUMN public.ad_lifetime.family_key IS 'Tracker family key (lower).';
COMMENT ON COLUMN public.ad_lifetime.spend IS 'Lifetime spend through the cutoff, dollars.';
COMMENT ON COLUMN public.ad_lifetime.purchases IS 'Lifetime Meta-reported purchases.';
COMMENT ON COLUMN public.ad_lifetime.conv_value IS 'Lifetime Meta-reported purchase value, dollars.';
COMMENT ON TABLE public.meta_family_map IS 'Maps every Meta ad family to a Creative Tracker family (the resolver''s output). The bridge between Meta numbers and tracker tags. Grain: one row per meta_family_key. Source: etl.resolve_families (ported resolver: exact / relaunch-encoded / ad-name / concept-prefix / product+type+version rules). Refresh: nightly (etl.run_daily): new families are mapped and previously unmatched ones retried; existing matches are left alone. Coverage: 16.1K Meta families, 4.1K matched. Caveats: tracker_family_key NULL = no tracker match (about 12K families, mostly old ads, ad copies by other names, and non-tracker products). | rule: ''exact'' | ''relaunch'' | ''adname'' | ''prefix'' | ''triple'' (and ''sheet-windows'' for legacy rows); NULL when unmatched.';
COMMENT ON COLUMN public.meta_family_map.meta_family_key IS 'lower(Meta ad family). Joins ad_daily.meta_family_key and meta_ads.meta_family_key.';
COMMENT ON COLUMN public.meta_family_map.meta_family IS 'Display name of the Meta family.';
COMMENT ON COLUMN public.meta_family_map.tracker_family_key IS 'Matched tracker family_key (lower), or NULL. Joins tracker_rows.family_key.';
COMMENT ON COLUMN public.meta_family_map.rule IS 'Which resolver rule matched.';
COMMENT ON COLUMN public.meta_family_map.resolved_at IS 'When the row was resolved.';
COMMENT ON TABLE public.upstack_attr_days IS 'Registry of the days whose Upstack Meta attribution was pulled completely (a day with zero Meta orders is still a pulled day). Grain: one row per day. Source: etl.upstack_daily (Upstack /api/query-attribution, any-click, 30-day window, utm_source ''Meta Ads''). Refresh: nightly (etl service 13:00 UTC): trailing 7 Pacific days re-pulled. Coverage: 2026-05-06 through yesterday (Pacific), 182 days. Caveats: Upstack''s own Meta attribution reaches back to 2025-05-13; this app loaded it from 2026-05-06, where its Meta daily data starts.';
COMMENT ON COLUMN public.upstack_attr_days.day IS 'Pacific day.';
COMMENT ON COLUMN public.upstack_attr_days.pulled_at IS 'When the day was last pulled.';
COMMENT ON COLUMN public.upstack_attr_days.campaigns IS 'Campaigns with orders or new customers that day.';
COMMENT ON COLUMN public.upstack_attr_days.ad_rows IS 'Ad-grain attribution rows pulled that day.';
COMMENT ON COLUMN public.upstack_attr_days.api_calls IS 'Upstack API calls the day took.';
COMMENT ON COLUMN public.upstack_attr_days.nc_campaigns IS 'New customers Upstack credits to Meta at campaign level (the total).';
COMMENT ON COLUMN public.upstack_attr_days.nc_ads IS 'The same, summed over the ad rows (the gap vs nc_campaigns = orders credited to a campaign but to no identifiable ad).';
COMMENT ON COLUMN public.upstack_attr_days.note IS 'Campaigns that came back without an ad split (''unidentified: ...'').';
COMMENT ON TABLE public.upstack_attr_daily IS 'Raw Upstack attribution at utm campaign x utm ad NAME grain (as clicked), before mapping to Meta ad ids. Grain: one row per (day, campaign, ad) where campaign and ad are utm values. Source: Upstack /api/query-attribution (dimension utm_campaign, then utm_ad per campaign), Meta Ads source. Refresh: nightly: trailing 7 days replaced. Coverage: 2026-05-06 through yesterday (Pacific), 27.7K rows. Caveats: Names, not ids: the same ad name in several ad sets is summed. ''(ad not identified)'' marks campaigns Upstack could not split by ad. | Any-click, 30-day window: an order is credited to every ad clicked in the 30 days before it. | Revenue is the order total with tax, before refunds.';
COMMENT ON COLUMN public.upstack_attr_daily.day IS 'Pacific day of the order.';
COMMENT ON COLUMN public.upstack_attr_daily.campaign IS 'utm_campaign value: usually the campaign NAME, sometimes a raw id or ''(not set)''.';
COMMENT ON COLUMN public.upstack_attr_daily.ad IS 'utm_ad value (ad name); ''(ad not identified)'' when Upstack could not split the campaign by ad.';
COMMENT ON COLUMN public.upstack_attr_daily.nc IS 'orders.new_customers: first-time customers credited.';
COMMENT ON COLUMN public.upstack_attr_daily.nc_rev IS 'orders.new_customer_total_revenue: their first-order revenue, dollars.';
COMMENT ON COLUMN public.upstack_attr_daily.orders IS 'orders.count: all orders credited.';
COMMENT ON COLUMN public.upstack_attr_daily.rev IS 'orders.total_revenue of those orders, dollars.';
COMMENT ON TABLE public.upstack_campaign_daily IS 'Upstack attribution totals per utm campaign and day (used for reconciliation against the ad-level rows). Grain: one row per (day, campaign). Source: Upstack /api/query-attribution, dimension utm_campaign, Meta Ads source. Refresh: nightly: trailing 7 days replaced. Coverage: 2026-05-06 through yesterday. Caveats: Campaign-level totals are higher than the ad-level rows by the orders Upstack credits to no identifiable ad (about 1.3% of orders).';
COMMENT ON COLUMN public.upstack_campaign_daily.day IS 'Pacific day.';
COMMENT ON COLUMN public.upstack_campaign_daily.campaign IS 'utm_campaign value.';
COMMENT ON COLUMN public.upstack_campaign_daily.nc IS 'New customers credited.';
COMMENT ON COLUMN public.upstack_campaign_daily.nc_rev IS 'Their first-order revenue, dollars.';
COMMENT ON COLUMN public.upstack_campaign_daily.orders IS 'All orders credited.';
COMMENT ON COLUMN public.upstack_campaign_daily.rev IS 'Revenue of all credited orders, dollars.';
COMMENT ON TABLE public.upstack_channel_daily IS 'Upstack''s own campaign-level ad-platform feed for Meta (spend, platform-reported purchases). Used only as the spend check: it equals Meta''s spend to the cent from 2026-08-01. Grain: one row per (day, Meta campaign_id). Source: Upstack /api/query-channel-details (campaign dimension, facebookIntegration rows). Refresh: nightly: trailing window replaced. Coverage: loaded for the backfill window; has no data before 2026-06-05 and a one-day shift between 2026-06-22 and 2026-07-07. Caveats: Not a source of truth for Meta spend: use ad_daily. Differences of 1-4% on a few October days come from the BackUp account''s New York day.';
COMMENT ON COLUMN public.upstack_channel_daily.day IS 'Day as Upstack buckets it (Pacific).';
COMMENT ON COLUMN public.upstack_channel_daily.campaign_id IS 'Meta campaign id.';
COMMENT ON COLUMN public.upstack_channel_daily.campaign_name IS 'Campaign name.';
COMMENT ON COLUMN public.upstack_channel_daily.spend IS 'Spend the feed reports, dollars.';
COMMENT ON COLUMN public.upstack_channel_daily.purchases IS 'Purchases the platform reports (delivered through Upstack).';
COMMENT ON COLUMN public.upstack_channel_daily.purchases_value IS 'Conversion value the platform reports, dollars.';
COMMENT ON COLUMN public.upstack_channel_daily.nc_purchases IS 'Platform-reported new-customer purchases.';
COMMENT ON COLUMN public.upstack_channel_daily.nc_purchases_value IS 'Their value, dollars.';
COMMENT ON COLUMN public.upstack_channel_daily.link_clicks IS 'Link clicks.';
COMMENT ON TABLE public.upstack_unmapped_daily IS 'Upstack attribution rows the build could not tie to a Meta ad. Kept out of every ad, family and tag total; the tie-out reports them. Grain: one row per (day, campaign, ad). Source: etl.upstack_build (rebuilt in full on every build). Refresh: nightly. Coverage: 2026-05-06 through yesterday; 521 rows (about 1.3% of orders). Caveats: reason: ''not_identified'' (no ad name / ''(not set)'' / ''(ad not identified)''), ''no_campaign'' (the utm campaign matches no Meta campaign), ''no_ad'' (campaign found, ad name not).';
COMMENT ON COLUMN public.upstack_unmapped_daily.day IS 'Pacific day.';
COMMENT ON COLUMN public.upstack_unmapped_daily.campaign IS 'utm_campaign value.';
COMMENT ON COLUMN public.upstack_unmapped_daily.ad IS 'utm_ad value.';
COMMENT ON COLUMN public.upstack_unmapped_daily.reason IS 'not_identified | no_campaign | no_ad.';
COMMENT ON COLUMN public.upstack_unmapped_daily.nc IS 'New customers credited.';
COMMENT ON COLUMN public.upstack_unmapped_daily.nc_rev IS 'Their first-order revenue, dollars.';
COMMENT ON COLUMN public.upstack_unmapped_daily.orders IS 'All orders credited.';
COMMENT ON COLUMN public.upstack_unmapped_daily.rev IS 'Revenue, dollars.';
COMMENT ON TABLE public.ad_daily_upstack IS 'ad_daily-shaped table for the Upstack source: Meta''s spend / clicks / impressions per ad and day plus the Upstack orders and new customers credited to each ad. Grain: one row per (ad_id, day) for every pulled day, plus rows for ads Upstack credited on days they had no ad_daily row. Source: etl.upstack_build: Meta spend copied from ad_daily for every pulled day (so a Meta restatement flows through) + Upstack attribution mapped from names to ad ids. Refresh: nightly (etl.upstack_daily): rebuilt in full from the stored raw pulls and the freshly refreshed ad_daily. Coverage: 2026-05-06 through yesterday (Pacific), 152K rows. Caveats: Upstack reports campaign and ad NAMES, not ids. Mapping rules in order: exact ad name inside the utm campaign, same family inside the campaign, exact name in any campaign, same family anywhere. Where several ads match (one ad copied into several ad sets) the day''s credit is split by each ad''s Meta spend that day (else lifetime spend, else equally) and always sums back exactly. | Any-click credits every ad clicked in the 30 days before an order, so ad-level credits overlap and rows exist with spend 0. | purchases / conv_value = ALL attributed orders; nc_purchases / nc_conv_value = first orders only (new customers).';
COMMENT ON COLUMN public.ad_daily_upstack.ad_id IS 'Meta ad id.';
COMMENT ON COLUMN public.ad_daily_upstack.day IS 'Pacific day.';
COMMENT ON COLUMN public.ad_daily_upstack.meta_family_key IS 'lower(ad family) of the ad''s current name.';
COMMENT ON COLUMN public.ad_daily_upstack.meta_family IS 'Ad family, original case.';
COMMENT ON COLUMN public.ad_daily_upstack.campaign_id IS 'Meta campaign id ('''' when unknown).';
COMMENT ON COLUMN public.ad_daily_upstack.spend IS 'Meta''s spend for the ad that day (copy of ad_daily; 0 on credit-only rows), dollars.';
COMMENT ON COLUMN public.ad_daily_upstack.purchases IS 'Upstack orders (new and returning customers) credited to the ad.';
COMMENT ON COLUMN public.ad_daily_upstack.conv_value IS 'Order revenue of those orders, dollars (tax included, before refunds).';
COMMENT ON COLUMN public.ad_daily_upstack.nc_purchases IS 'Upstack new customers (first orders) credited to the ad.';
COMMENT ON COLUMN public.ad_daily_upstack.nc_conv_value IS 'First-order revenue of those new customers, dollars.';
COMMENT ON COLUMN public.ad_daily_upstack.link_clicks IS 'Meta link clicks (copy of ad_daily).';
COMMENT ON COLUMN public.ad_daily_upstack.impressions IS 'Meta impressions (copy of ad_daily).';
COMMENT ON COLUMN public.ad_daily_upstack.source IS '''upstack''.';
COMMENT ON COLUMN public.ad_daily_upstack.loaded_at IS 'When the table was built.';
COMMENT ON VIEW public.ad_daily_upstack_nc IS 'View over ad_daily_upstack with the exact column set of ad_daily, on the NEW-CUSTOMER basis: purchases = nc_purchases, conv_value = nc_conv_value. Lets the app run the same SQL on either source. Grain: one row per (ad_id, day). Source: public.ad_daily_upstack. Refresh: live view. Coverage: as ad_daily_upstack. Caveats: Spend, clicks, impressions are Meta''s; only purchases / conv_value change meaning.';
COMMENT ON COLUMN public.ad_daily_upstack_nc.ad_id IS 'Meta ad id (text). ''fam:<family key>'' on legacy family-grain rows.';
COMMENT ON COLUMN public.ad_daily_upstack_nc.day IS 'Calendar day in the ad account''s own timezone.';
COMMENT ON COLUMN public.ad_daily_upstack_nc.meta_family_key IS 'lower(ad family).';
COMMENT ON COLUMN public.ad_daily_upstack_nc.meta_family IS 'Ad family, original case.';
COMMENT ON COLUMN public.ad_daily_upstack_nc.campaign_id IS 'Meta campaign id.';
COMMENT ON COLUMN public.ad_daily_upstack_nc.spend IS 'Meta''s spend (copy), dollars.';
COMMENT ON COLUMN public.ad_daily_upstack_nc.purchases IS 'Upstack new customers (first orders) credited to the ad.';
COMMENT ON COLUMN public.ad_daily_upstack_nc.conv_value IS 'Their first-order revenue, dollars.';
COMMENT ON COLUMN public.ad_daily_upstack_nc.link_clicks IS 'Meta link clicks (copy).';
COMMENT ON COLUMN public.ad_daily_upstack_nc.source IS '''upstack''.';
COMMENT ON COLUMN public.ad_daily_upstack_nc.loaded_at IS 'When ad_daily_upstack was built.';
COMMENT ON COLUMN public.ad_daily_upstack_nc.impressions IS 'Meta impressions (copy).';
COMMENT ON VIEW public.ad_daily_upstack_all IS 'View over ad_daily_upstack with the exact column set of ad_daily, on the ALL-ORDERS basis: purchases = purchases, conv_value = conv_value (every credited order). Grain: one row per (ad_id, day). Source: public.ad_daily_upstack. Refresh: live view. Coverage: as ad_daily_upstack. Caveats: Spend, clicks, impressions are Meta''s; only purchases / conv_value change meaning.';
COMMENT ON COLUMN public.ad_daily_upstack_all.ad_id IS 'Meta ad id (text). ''fam:<family key>'' on legacy family-grain rows.';
COMMENT ON COLUMN public.ad_daily_upstack_all.day IS 'Calendar day in the ad account''s own timezone.';
COMMENT ON COLUMN public.ad_daily_upstack_all.meta_family_key IS 'lower(ad family).';
COMMENT ON COLUMN public.ad_daily_upstack_all.meta_family IS 'Ad family, original case.';
COMMENT ON COLUMN public.ad_daily_upstack_all.campaign_id IS 'Meta campaign id.';
COMMENT ON COLUMN public.ad_daily_upstack_all.spend IS 'Meta''s spend (copy), dollars.';
COMMENT ON COLUMN public.ad_daily_upstack_all.purchases IS 'All Upstack orders credited to the ad.';
COMMENT ON COLUMN public.ad_daily_upstack_all.conv_value IS 'Revenue of those orders, dollars.';
COMMENT ON COLUMN public.ad_daily_upstack_all.link_clicks IS 'Meta link clicks (copy).';
COMMENT ON COLUMN public.ad_daily_upstack_all.source IS '''upstack''.';
COMMENT ON COLUMN public.ad_daily_upstack_all.loaded_at IS 'When ad_daily_upstack was built.';
COMMENT ON COLUMN public.ad_daily_upstack_all.impressions IS 'Meta impressions (copy).';
COMMENT ON VIEW public.meta_ad_lifetime_upstack_nc IS 'Since-launch per ad on the Upstack new-customer basis = every day held in ad_daily_upstack (Upstack has no all-time endpoint at ad grain). Grain: one row per ad_id. Source: public.ad_daily_upstack_nc grouped by ad. Refresh: live view. Coverage: 2026-05-06 onward. Caveats: ''Since launch'' here is since 2026-05-06, not the ad''s real launch.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_nc.ad_id IS 'Meta ad id.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_nc.meta_family_key IS 'lower(ad family).';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_nc.tracker_family_key IS 'NULL.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_nc.spend IS 'Meta spend over the days held.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_nc.purchases IS 'Upstack new customers over the days held.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_nc.conv_value IS 'Their first-order revenue, dollars.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_nc.impressions IS 'Impressions over the days held.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_nc.link_clicks IS 'Link clicks over the days held.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_nc.source IS '''meta_api''.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_nc.pulled_at IS 'Latest loaded_at.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_nc.first_day IS 'First day held for the ad.';
COMMENT ON VIEW public.meta_ad_lifetime_upstack_all IS 'Since-launch per ad on the Upstack all-orders basis = every day held in ad_daily_upstack. Grain: one row per ad_id. Source: public.ad_daily_upstack_all grouped by ad. Refresh: live view. Coverage: 2026-05-06 onward. Caveats: ''Since launch'' here is since 2026-05-06, not the ad''s real launch.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_all.ad_id IS 'Meta ad id.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_all.meta_family_key IS 'lower(ad family).';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_all.tracker_family_key IS 'NULL.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_all.spend IS 'Meta spend over the days held.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_all.purchases IS 'All Upstack orders credited over the days held.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_all.conv_value IS 'Their revenue, dollars.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_all.impressions IS 'Impressions over the days held.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_all.link_clicks IS 'Link clicks over the days held.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_all.source IS '''meta_api''.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_all.pulled_at IS 'Latest loaded_at.';
COMMENT ON COLUMN public.meta_ad_lifetime_upstack_all.first_day IS 'First day held for the ad.';
COMMENT ON TABLE public.upstack_google_campaigns IS 'Google Ads campaign dimension from the Upstack channel feed. Grain: one row per Google campaign_id. Source: Upstack /api/query-channel-details (googleAdsIntegration rows); campaign_type derived from the name by etl.upstack_google.campaign_type. Refresh: nightly (etl.upstack_daily). Coverage: 90 campaigns. Caveats: Upstack exposes no campaign type; it is read from the campaign name (''PMax'' = Performance Max, ''DG..'' / ''IL | Demand Gen'' = Demand Gen, ''Standard Shopping'' / ''SS |'' = Shopping, ''Brand / Prospecting / Competitors Search'' = Search, anything else = Other).';
COMMENT ON COLUMN public.upstack_google_campaigns.campaign_id IS 'Google campaign id.';
COMMENT ON COLUMN public.upstack_google_campaigns.name IS 'Campaign name.';
COMMENT ON COLUMN public.upstack_google_campaigns.status IS 'Campaign status as the feed reports it.';
COMMENT ON COLUMN public.upstack_google_campaigns.bid_strategy IS 'Bid strategy as the feed reports it.';
COMMENT ON COLUMN public.upstack_google_campaigns.campaign_type IS 'Shopping | Search | Performance Max | Demand Gen | Other.';
COMMENT ON COLUMN public.upstack_google_campaigns.updated_at IS 'When the row was last refreshed.';
COMMENT ON TABLE public.upstack_google_channel_daily IS 'Google''s own daily numbers per campaign (spend, impressions, clicks, conversions) delivered through Upstack''s ad-platform feed. Grain: one row per (day, campaign_id); zero-activity days are not stored. Source: Upstack /api/query-channel-details, Google rows, campaign grain, Pacific days. Refresh: nightly: trailing window replaced. Coverage: 2024-03-25 (first day with Google spend) through yesterday; 8.9K rows. Caveats: Google restates conversions after the fact, so purchases / purchases_value of recent days move by up to about 1%. | Google''s new-customer measures are empty in this feed: there is no Google-reported new-customer number, only Upstack''s attribution.';
COMMENT ON COLUMN public.upstack_google_channel_daily.day IS 'Pacific day.';
COMMENT ON COLUMN public.upstack_google_channel_daily.campaign_id IS 'Google campaign id.';
COMMENT ON COLUMN public.upstack_google_channel_daily.spend IS 'Spend, dollars.';
COMMENT ON COLUMN public.upstack_google_channel_daily.impressions IS 'Impressions.';
COMMENT ON COLUMN public.upstack_google_channel_daily.clicks IS 'Clicks (all clicks).';
COMMENT ON COLUMN public.upstack_google_channel_daily.purchases IS 'Purchases Google counts (channel.purchases).';
COMMENT ON COLUMN public.upstack_google_channel_daily.purchases_value IS 'Conversion value Google reports, dollars.';
COMMENT ON TABLE public.upstack_google_attr_daily IS 'Raw Upstack attribution for Google Ads at utm campaign NAME grain. Grain: one row per (day, campaign). Source: Upstack /api/query-attribution, utm_source ''Google Ads'', any-click, 30-day window. Refresh: nightly: trailing 7 days replaced. Coverage: 2025-05-13 (first day Upstack has any attribution) through yesterday; 4.8K rows. Caveats: Any-click credits Google with orders that also had a Meta click, so Upstack''s Google orders exceed Google''s own count (about 536 vs 339 over 30 days in Oct 2026).';
COMMENT ON COLUMN public.upstack_google_attr_daily.day IS 'Pacific day of the order.';
COMMENT ON COLUMN public.upstack_google_attr_daily.campaign IS 'utm_campaign value as clicked.';
COMMENT ON COLUMN public.upstack_google_attr_daily.nc IS 'orders.new_customers.';
COMMENT ON COLUMN public.upstack_google_attr_daily.nc_rev IS 'orders.new_customer_total_revenue, dollars.';
COMMENT ON COLUMN public.upstack_google_attr_daily.orders IS 'orders.count.';
COMMENT ON COLUMN public.upstack_google_attr_daily.rev IS 'orders.total_revenue, dollars.';
COMMENT ON TABLE public.upstack_google_days IS 'Registry of the days whose Google attribution was pulled completely. Grain: one row per day. Source: etl.upstack_google. Refresh: nightly. Coverage: 2025-05-13 through yesterday, 540 days.';
COMMENT ON COLUMN public.upstack_google_days.day IS 'Pacific day.';
COMMENT ON COLUMN public.upstack_google_days.pulled_at IS 'When the day was last pulled.';
COMMENT ON COLUMN public.upstack_google_days.campaigns IS 'utm campaigns with attribution that day.';
COMMENT ON COLUMN public.upstack_google_days.nc IS 'New customers Upstack credits to Google that day.';
COMMENT ON COLUMN public.upstack_google_days.orders IS 'Orders Upstack credits to Google that day.';
COMMENT ON TABLE public.google_daily IS 'Derived Google campaign x day table: the channel feed rows joined to the attribution rows by campaign name. Behind analytics.google_campaign_daily. Grain: one row per (day, campaign_key). Source: etl.upstack_google.build (rebuilt in full from upstack_google_channel_daily + upstack_google_attr_daily). Refresh: nightly (etl.upstack_daily). Coverage: 2024-03-25 through yesterday (Pacific); 9.4K rows. Caveats: Attribution is keyed by campaign NAME; when two campaign ids share a name its numbers go to the one with the most spend. | Before 2025-05-13 the nc / nc_rev / orders / rev columns are 0 because Upstack had no attribution then, NOT because there were no orders; analytics.google_campaign_daily turns those into NULL. | in_feed = false rows are utm campaigns that match no Google campaign (spend 0).';
COMMENT ON COLUMN public.google_daily.day IS 'Pacific day.';
COMMENT ON COLUMN public.google_daily.campaign_key IS 'Google campaign id, or ''name:<utm campaign>'' for in_feed = false rows.';
COMMENT ON COLUMN public.google_daily.campaign_name IS 'Campaign name.';
COMMENT ON COLUMN public.google_daily.campaign_type IS 'Shopping | Search | Performance Max | Demand Gen | Other.';
COMMENT ON COLUMN public.google_daily.in_feed IS 'true = a campaign of the Google channel feed.';
COMMENT ON COLUMN public.google_daily.spend IS 'Google spend, dollars.';
COMMENT ON COLUMN public.google_daily.impressions IS 'Impressions.';
COMMENT ON COLUMN public.google_daily.clicks IS 'Clicks.';
COMMENT ON COLUMN public.google_daily.purchases IS 'Google-reported purchases.';
COMMENT ON COLUMN public.google_daily.purchases_value IS 'Google-reported conversion value, dollars.';
COMMENT ON COLUMN public.google_daily.nc IS 'Upstack new customers credited (attribution).';
COMMENT ON COLUMN public.google_daily.nc_rev IS 'Their first-order revenue, dollars.';
COMMENT ON COLUMN public.google_daily.orders IS 'Upstack orders credited.';
COMMENT ON COLUMN public.google_daily.rev IS 'Their revenue, dollars.';
COMMENT ON TABLE public.upstack_orders_daily IS 'The business''s actual revenue and customers per Pacific day, counted once. Numerator of Total NC ROAS. Behind analytics.orders_daily. Grain: one row per Pacific day. Source: Upstack /api/query, orders.* measures, granularity day, America/Los_Angeles (etl.upstack_orders). Refresh: nightly (etl.upstack_daily): trailing 7 days replaced; the job refuses an empty answer. Coverage: 2025-01-01 through yesterday, 672 days. Caveats: Order totals include tax, before refunds. No product / platform dimension. A day with no orders is absent.';
COMMENT ON COLUMN public.upstack_orders_daily.day IS 'Pacific day.';
COMMENT ON COLUMN public.upstack_orders_daily.nc_rev IS 'orders.new_customer_total_revenue: first-order revenue, dollars.';
COMMENT ON COLUMN public.upstack_orders_daily.rc_rev IS 'orders.returning_customer_total_revenue: repeat-order revenue, dollars.';
COMMENT ON COLUMN public.upstack_orders_daily.nc_orders IS 'orders.new_customers: number of new customers.';
COMMENT ON COLUMN public.upstack_orders_daily.total_rev IS 'orders.total_revenue, dollars.';
COMMENT ON COLUMN public.upstack_orders_daily.orders IS 'orders.count: all orders.';
COMMENT ON COLUMN public.upstack_orders_daily.pulled_at IS 'When the day was last pulled.';
COMMENT ON TABLE public.products IS 'The product list (Vita Bull, Beef Liver, Boneflex, Vita Belle, Vital Flow, plus ''unassigned'') and the rules that route tracker rows and Meta ads to a product. Grain: one row per product. Source: seeded by migration 001; tag_set is flipped to ''linemap'' by etl.load_tags once a product''s line-map coverage is high enough. Refresh: rarely changes. Coverage: 6 rows. Caveats: meta_regex is applied (case-insensitive, lowest meta_priority first) to a Meta family name to guess a product for ads that are on no tracker row. | tag_set: which ad_tags.tag_set drives the hierarchy for the product: ''linemap'' (Communication Overview line) or ''tracker'' (the tracker''s own columns).';
COMMENT ON COLUMN public.products.id IS 'Primary key.';
COMMENT ON COLUMN public.products.slug IS '''vita-bull'' | ''beef-liver'' | ''boneflex'' | ''vita-belle'' | ''vital-flow'' | ''unassigned''.';
COMMENT ON COLUMN public.products.name IS 'Display name.';
COMMENT ON COLUMN public.products.tracker_names IS 'Values of the Creative Tracker ''Product'' column that map to this product (array).';
COMMENT ON COLUMN public.products.meta_regex IS 'Regular expression used to guess the product from a Meta family name (NULL for ''unassigned'').';
COMMENT ON COLUMN public.products.meta_priority IS 'Lower is tested first.';
COMMENT ON COLUMN public.products.tag_set IS '''linemap'' | ''tracker''.';
COMMENT ON COLUMN public.products.sort_order IS 'Display order.';
COMMENT ON COLUMN public.products.active IS 'false hides the product from the Products table.';
COMMENT ON TABLE public.taxonomy_lines IS 'The Communication Overview: one line per market cluster x ICP x pain point x emotional trigger for each product (codes L01.. Vita Bull, B01.. Beef Liver, BF01.. Boneflex). Grain: one row per line (product_id, line_code). Source: Creative Key sheet tab ''Communication Overview'' via etl.load_taxonomy. Refresh: manual (run etl.load_taxonomy after the sheet changes); not in the nightly cron. Coverage: 157 lines. Caveats: Codes are stable across reloads; a changed trigger keeps its row and code. | added_after_tagging = true marks a line the sheet gained after the ads were tagged: it reads 0 ads by construction, not ''untested''.';
COMMENT ON COLUMN public.taxonomy_lines.id IS 'Primary key.';
COMMENT ON COLUMN public.taxonomy_lines.product_id IS 'products.id.';
COMMENT ON COLUMN public.taxonomy_lines.line_code IS 'L01.. / B01.. / BF01.. (unique per product).';
COMMENT ON COLUMN public.taxonomy_lines.cluster IS 'Market cluster.';
COMMENT ON COLUMN public.taxonomy_lines.icp IS 'Ideal customer profile / persona.';
COMMENT ON COLUMN public.taxonomy_lines.pain_point IS 'Pain point.';
COMMENT ON COLUMN public.taxonomy_lines.emotional_trigger IS 'Emotional trigger (can be NULL).';
COMMENT ON COLUMN public.taxonomy_lines.story IS 'Short story the ad would tell (15 words or fewer).';
COMMENT ON COLUMN public.taxonomy_lines.cluster_color IS 'Hex colour of the cluster in the sheet.';
COMMENT ON COLUMN public.taxonomy_lines.sort_order IS 'Communication Overview order.';
COMMENT ON COLUMN public.taxonomy_lines.added_after_tagging IS 'true = the line was added after the product''s ads were tagged.';
COMMENT ON TABLE public.line_ingredients IS 'Ingredient rows that hang off a taxonomy line: what each ingredient attacks and supports. Grain: one row per (line, ingredient). Source: Creative Key sheet tab ''Communication Overview'' via etl.load_taxonomy. Refresh: manual with load_taxonomy. Coverage: 285 rows.';
COMMENT ON COLUMN public.line_ingredients.id IS 'Primary key.';
COMMENT ON COLUMN public.line_ingredients.line_id IS 'taxonomy_lines.id.';
COMMENT ON COLUMN public.line_ingredients.ingredient IS 'Nutrient / active compound that addresses the pain point (e.g. Zinc, Heme Iron, Glucosamine).';
COMMENT ON COLUMN public.line_ingredients.attacks IS '''What It Attacks'': the mechanism it counters.';
COMMENT ON COLUMN public.line_ingredients.supports IS '''What It Supports''.';
COMMENT ON COLUMN public.line_ingredients.sort_order IS 'Order within the line.';
COMMENT ON TABLE public.tracker_rows IS 'Creative Tracker rows for every product: one row per concept / ad variant with its status, copy, transcript and the tracker''s own tags. Grain: one row per tracker row (row_key); an ad family (family_key) can span several rows. Source: Creative Key Google Sheet tab ''Creative Tracker'' via etl.tracker_sync. Refresh: nightly (etl.run_daily); the sync is refused (no writes) on a renamed required header or a >20% jump in blank families / drop in rows. Coverage: 3,982 rows (3,980 live). Caveats: Identity is row_key = concept_id + ''#'' + ordinal, never the sheet row. concept_id is text (''0510'' is not ''510''). | family_key = lower(ad_family), or ''id:'' + lower(concept_id) when the family is blank; rows with a blank family can never match Meta spend. | Rows the sheet no longer has get deleted_at (never removed); deleted rows are ignored by the metrics. | launch_date is a date typed by the team, not a Meta field.';
COMMENT ON COLUMN public.tracker_rows.id IS 'Primary key.';
COMMENT ON COLUMN public.tracker_rows.product_id IS 'products.id.';
COMMENT ON COLUMN public.tracker_rows.row_key IS 'Stable row key (''<concept id>#<n>'').';
COMMENT ON COLUMN public.tracker_rows.concept_id IS 'Tracker Concept ID (text).';
COMMENT ON COLUMN public.tracker_rows.ad_family IS 'Tracker ''Ad Family'' as typed ('''' when blank).';
COMMENT ON COLUMN public.tracker_rows.family_key IS 'The unique-ad key (see caveat).';
COMMENT ON COLUMN public.tracker_rows.sheet_row IS 'Row number on the sheet; informational, used only to order rows (the first row of a family has the lowest).';
COMMENT ON COLUMN public.tracker_rows.status IS 'Tracker status.';
COMMENT ON COLUMN public.tracker_rows.ad_type IS 'VID | IMG.';
COMMENT ON COLUMN public.tracker_rows.style IS 'Creative style.';
COMMENT ON COLUMN public.tracker_rows.vendor IS 'Creative vendor.';
COMMENT ON COLUMN public.tracker_rows.fidelity IS 'Creative fidelity.';
COMMENT ON COLUMN public.tracker_rows.proof IS 'Proof mechanism.';
COMMENT ON COLUMN public.tracker_rows.launch_date IS 'Launch date from the tracker.';
COMMENT ON COLUMN public.tracker_rows.concept_name IS 'Concept name.';
COMMENT ON COLUMN public.tracker_rows.description IS 'Short description.';
COMMENT ON COLUMN public.tracker_rows.hypothesis IS 'Why the concept is tested.';
COMMENT ON COLUMN public.tracker_rows.meta_ad_name IS 'Ad name in Meta (tracker ''Name'' column).';
COMMENT ON COLUMN public.tracker_rows.primary_text IS 'Primary text 1-3 (array).';
COMMENT ON COLUMN public.tracker_rows.headlines IS 'Headlines 1-3 (array).';
COMMENT ON COLUMN public.tracker_rows.ad_description IS 'Ad description.';
COMMENT ON COLUMN public.tracker_rows.transcript IS 'Video transcript from the tracker.';
COMMENT ON COLUMN public.tracker_rows.asset_url IS 'Link to the creative asset.';
COMMENT ON COLUMN public.tracker_rows.tracker_cluster IS 'Tracker''s Market Cluster.';
COMMENT ON COLUMN public.tracker_rows.tracker_icp IS 'Tracker''s ICP (persona).';
COMMENT ON COLUMN public.tracker_rows.tracker_icp_legacy IS 'The older ICP column kept by the team.';
COMMENT ON COLUMN public.tracker_rows.tracker_pain IS 'Tracker''s Pain Point.';
COMMENT ON COLUMN public.tracker_rows.tracker_emotion IS 'Tracker''s Emotion.';
COMMENT ON COLUMN public.tracker_rows.tracker_ingredient IS 'Tracker''s Lead Ingredient.';
COMMENT ON COLUMN public.tracker_rows.raw IS 'Every tracker column by header (jsonb). Free-form; not exposed in analytics.';
COMMENT ON COLUMN public.tracker_rows.synced_at IS 'Last sync that saw the row.';
COMMENT ON COLUMN public.tracker_rows.deleted_at IS 'Set when a sync no longer sees the row; cleared if it reappears.';
COMMENT ON COLUMN public.tracker_rows.fingerprint IS 'md5 of concept name | description | hypothesis | brief date: the stable identity for duplicate (concept, family) groups.';
COMMENT ON TABLE public.ad_tags IS 'Tags per tracker row. ''linemap'' = the Communication Overview line a tagger chose after looking at the creative; ''tracker'' = the tracker''s own Market Cluster / ICP / Pain Point. Grain: one current row per (tracker_row_id, tag_set); older versions kept with is_current = false. Source: tag_set ''tracker'': etl.tracker_sync on every sync (version ''tracker-live''); ''linemap'': etl.load_tags from a tagging cycle file (Sonnet taggers reading the image / video frames + transcript). Refresh: ''tracker'' nightly; ''linemap'' by hand per cycle (versions dated 2026-11-03, 2026-11-04, 2026-11-05). Coverage: 7.8K rows (3.8K current linemap rows for Vita Bull / Beef Liver / Boneflex). Caveats: Confidence and method matter: ''text only'' / ''no picture (copy only)'' tags came from copy alone (about 580 rows) and are the weakest; high-confidence image / video tags are the most reliable. | A tracker row with no current tag in the product''s tag_set shows as ''(untagged)'' in the app.';
COMMENT ON COLUMN public.ad_tags.id IS 'Primary key.';
COMMENT ON COLUMN public.ad_tags.tracker_row_id IS 'tracker_rows.id.';
COMMENT ON COLUMN public.ad_tags.tag_set IS '''linemap'' | ''tracker''.';
COMMENT ON COLUMN public.ad_tags.version IS 'Tagging cycle, e.g. ''linemap-v2-2026-11-03'', ''tracker-live''.';
COMMENT ON COLUMN public.ad_tags.is_current IS 'true for the tag in force.';
COMMENT ON COLUMN public.ad_tags.line_id IS 'taxonomy_lines.id (linemap tags).';
COMMENT ON COLUMN public.ad_tags.cluster IS 'Market cluster.';
COMMENT ON COLUMN public.ad_tags.icp IS 'ICP / persona.';
COMMENT ON COLUMN public.ad_tags.pain_point IS 'Pain point.';
COMMENT ON COLUMN public.ad_tags.emotional_trigger IS 'Emotional trigger.';
COMMENT ON COLUMN public.ad_tags.confidence IS 'high | medium | low | NULL.';
COMMENT ON COLUMN public.ad_tags.method IS 'How it was tagged: ''image'', ''video: 4 frames + Whisper transcript'', ''text only'', ''no picture (copy only)'', ''video: thumbnail + no audio'' ...';
COMMENT ON COLUMN public.ad_tags.seen IS '''What Was Seen'': the tagger''s description of the creative.';
COMMENT ON COLUMN public.ad_tags.why IS 'Why the line was chosen.';
COMMENT ON COLUMN public.ad_tags.runner_up IS 'Second-best line.';
COMMENT ON COLUMN public.ad_tags.copy_only_line IS 'Line the copy-only first pass picked when different.';
COMMENT ON COLUMN public.ad_tags.tagger IS 'Who / what tagged it.';
COMMENT ON COLUMN public.ad_tags.tagged_at IS 'When the tag was written.';
COMMENT ON COLUMN public.ad_tags.extra IS 'Cycle-specific extras (jsonb): what was heard, gaps, media notes.';
COMMENT ON TABLE public.ad_hooks IS 'One hook per tracker row: the ad''s first spoken line plus on-image headline boiled down to one short line. Grain: one row per tracker_row_id. Source: etl.load_hooks from an extraction cycle file (Sonnet reading the opening frame and the first transcript sentences). Refresh: manual per cycle; a newer version replaces the older hook of every row it covers. Coverage: 3.4K rows (about 82% / 87% / 94% of the Vita Bull / Beef Liver / Boneflex tracker rows). Caveats: Rows without a readable source (silent videos, missing thumbnails, no copy) have no hook. About 120 hooks run past 18 words.';
COMMENT ON COLUMN public.ad_hooks.tracker_row_id IS 'tracker_rows.id (primary key).';
COMMENT ON COLUMN public.ad_hooks.hook IS 'The one-line hook.';
COMMENT ON COLUMN public.ad_hooks.spoken IS 'First spoken line (video audio / transcript).';
COMMENT ON COLUMN public.ad_hooks.on_screen IS 'On-image headline / first on-screen text.';
COMMENT ON COLUMN public.ad_hooks.hook_source IS 'spoken | on_screen | both | copy | none.';
COMMENT ON COLUMN public.ad_hooks.confidence IS 'high | medium | low.';
COMMENT ON COLUMN public.ad_hooks.note IS 'Extractor remark.';
COMMENT ON COLUMN public.ad_hooks.version IS 'Extraction cycle, e.g. ''hooks-v1-2026-11-05''.';
COMMENT ON COLUMN public.ad_hooks.extractor IS 'Who produced it.';
COMMENT ON COLUMN public.ad_hooks.extracted_at IS 'When the row was written.';
COMMENT ON TABLE public.family_content IS 'Per tracker family: the copy Meta runs, transcript, post link. Feeds the ad page of the app. Grain: one row per tracker family_key. Source: etl.load_assets from a tagging cycle folder (Meta copy, whisper transcripts, tracker transcripts). Refresh: manual per cycle. Coverage: 3.7K families.';
COMMENT ON COLUMN public.family_content.family_key IS 'Tracker family key (primary key).';
COMMENT ON COLUMN public.family_content.meta_body IS 'Primary text Meta runs.';
COMMENT ON COLUMN public.family_content.meta_title IS 'Headline Meta runs.';
COMMENT ON COLUMN public.family_content.meta_desc IS 'Link description Meta runs.';
COMMENT ON COLUMN public.family_content.transcript IS 'Video transcript used by the taggers.';
COMMENT ON COLUMN public.family_content.transcript_seconds IS 'Length of the transcribed audio.';
COMMENT ON COLUMN public.family_content.story_url IS 'Facebook post link.';
COMMENT ON COLUMN public.family_content.is_video IS 'true for video ads.';
COMMENT ON COLUMN public.family_content.ad_id IS 'A Meta ad id of the family.';
COMMENT ON COLUMN public.family_content.video_id IS 'Meta video id.';
COMMENT ON COLUMN public.family_content.source IS '''cycle-2026-11-04'', ''cycle-2026-11-04:whisper'', ''cycle-2026-11-03:tracker'' ...';
COMMENT ON TABLE public.creative_assets IS 'Creative thumbnails and video frames (image bytes) per tracker family, shown in the app. The only binary data in the database. Grain: one row per (family_key, kind, idx). Source: etl.load_assets (tagging cycle media) and etl.assets_pull (Meta Graph thumbnails, best effort). Refresh: manual / best effort. Coverage: 10.6K images. Caveats: bytes holds the JPEG itself: never SELECT it casually.';
COMMENT ON COLUMN public.creative_assets.id IS 'Primary key.';
COMMENT ON COLUMN public.creative_assets.family_key IS 'Tracker family key.';
COMMENT ON COLUMN public.creative_assets.kind IS '''thumb'' | ''frame''.';
COMMENT ON COLUMN public.creative_assets.idx IS 'Frame index (0 for a thumb).';
COMMENT ON COLUMN public.creative_assets.mime IS 'Image mime type.';
COMMENT ON COLUMN public.creative_assets.width IS 'Pixel width.';
COMMENT ON COLUMN public.creative_assets.height IS 'Pixel height.';
COMMENT ON COLUMN public.creative_assets.bytes IS 'The image bytes.';
COMMENT ON COLUMN public.creative_assets.source IS '''cycle-2026-11-03'' | ''meta-api'' ...';
COMMENT ON COLUMN public.creative_assets.created_at IS 'When loaded.';
COMMENT ON TABLE public.family_daily IS 'ad_daily re-keyed to the TRACKER family (through meta_family_map) and split by campaign stage. Powers any date window in the app without scanning ad_daily. Grain: one row per (family_key, day, stage). Source: etl.build_metrics from ad_daily + meta_ads + meta_family_map + meta_campaigns (Meta-reported). Refresh: nightly: TRUNCATE and rebuild in the same transaction as the Meta pull. Coverage: 2026-05-06 through yesterday; only Meta families that map to a tracker family. Caveats: Meta families with no tracker match are NOT here (see unmatched_meta), so this table does not sum to the account''s spend. | A family mapped by two Meta families sums both. The table is derived: query ad_daily or analytics.meta_ad_daily for account totals. | Traffic columns: clicks_tr and spend_tr are the base for CTR / CPC / CPM: clicks_tr = link clicks on rows that carry impressions, spend_tr = spend on those rows.';
COMMENT ON COLUMN public.family_daily.family_key IS 'Tracker family key (lower).';
COMMENT ON COLUMN public.family_daily.day IS 'Day (Meta ad account day).';
COMMENT ON COLUMN public.family_daily.stage IS '''testing'' | ''scaling'' | ''unclassified'' (days with no campaign).';
COMMENT ON COLUMN public.family_daily.spend IS 'Meta spend, dollars.';
COMMENT ON COLUMN public.family_daily.purchases IS 'Meta-reported purchases.';
COMMENT ON COLUMN public.family_daily.revenue IS 'Meta-reported purchase value, dollars.';
COMMENT ON COLUMN public.family_daily.link_clicks IS 'Link clicks.';
COMMENT ON COLUMN public.family_daily.impressions IS 'Impressions over rows that carry them.';
COMMENT ON COLUMN public.family_daily.clicks_tr IS 'Link clicks on rows with impressions (CTR numerator).';
COMMENT ON COLUMN public.family_daily.spend_tr IS 'Spend on rows with impressions (CPC / CPM base).';
COMMENT ON TABLE public.family_daily_active IS 'family_daily restricted to Meta ads whose CURRENT status is ACTIVE (''what the currently active ads did''). Grain: one row per (family_key, day, stage). Source: etl.build_metrics (ad_daily joined to ACTIVE meta_ads). Refresh: nightly rebuild. Coverage: 2.4K rows: only ads active now (about 441), so recent days mostly. Caveats: Current status is applied to the whole history of the ad.';
COMMENT ON COLUMN public.family_daily_active.family_key IS 'Tracker family key (lower).';
COMMENT ON COLUMN public.family_daily_active.day IS 'Day (Meta ad account day).';
COMMENT ON COLUMN public.family_daily_active.stage IS '''testing'' | ''scaling'' | ''unclassified'' (days with no campaign).';
COMMENT ON COLUMN public.family_daily_active.spend IS 'Meta spend, dollars.';
COMMENT ON COLUMN public.family_daily_active.purchases IS 'Meta-reported purchases.';
COMMENT ON COLUMN public.family_daily_active.revenue IS 'Meta-reported purchase value, dollars.';
COMMENT ON COLUMN public.family_daily_active.link_clicks IS 'Link clicks.';
COMMENT ON COLUMN public.family_daily_active.impressions IS 'Impressions over rows that carry them.';
COMMENT ON COLUMN public.family_daily_active.clicks_tr IS 'Link clicks on rows with impressions (CTR numerator).';
COMMENT ON COLUMN public.family_daily_active.spend_tr IS 'Spend on rows with impressions (CPC / CPM base).';
